/**
 * Glossary of technical terms used across lessons, missions and interview
 * questions. Every term is matched automatically in rendered Markdown (first
 * occurrence per block of content) and becomes tappable.
 *
 * Writing rule: `short` is one plain sentence a newcomer can understand.
 * `detail` adds the engineering precision. `why` says what it means for her
 * work or an interview. No jargon in `short` that is not itself in the glossary.
 */
export type GlossaryTerm = {
  id: string;
  term: string;
  /** Other spellings or phrases that should match, case-insensitive. */
  aliases?: string[];
  short: string;
  detail: string;
  why: string;
  relatedLesson?: string;
};

export const glossary: GlossaryTerm[] = [
  // --- Microcontroller basics ---
  { id: "mcu", term: "MCU", aliases: ["microcontroller", "microcontrollers"], short: "A small computer on one chip: processor, memory and peripherals such as timers and serial ports.", detail: "Microcontrollers (MCUs) run a single firmware program directly from on-chip flash, with no operating system required. STM32 is a popular family built on Arm Cortex-M cores.", why: "Every embedded role assumes you can describe what is inside an MCU and how firmware reaches its first instruction.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "firmware", term: "firmware", short: "The program stored permanently inside a device, running directly on the hardware.", detail: "Firmware is compiled C or C++ written into the MCU's flash memory. It configures peripherals by writing registers and reacts to events through interrupts.", why: "Interviewers will ask you to separate hardware causes from firmware causes when a board misbehaves." },
  { id: "register", term: "register", aliases: ["registers", "peripheral register", "memory-mapped register"], short: "A fixed location in the chip's address space whose bits control or report a piece of hardware.", detail: "Peripheral registers are memory-mapped: writing to an address such as 0x4002 0000 changes a GPIO port's configuration rather than storing a value in RAM. Each register is divided into bits and fields documented in the reference manual.", why: "Reading a register description and changing exactly the right bits is the core skill of register-level embedded C.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "peripheral", term: "peripheral", aliases: ["peripherals"], short: "A hardware block inside the MCU that does a job for the processor: a timer, an I2C port, a GPIO bank.", detail: "Peripherals are configured and read through their registers. Most need their clock enabled in the RCC before they respond at all.", why: "Forgetting to enable a peripheral clock is one of the most common bring-up mistakes and a favourite interview trap." },
  { id: "gpio", term: "GPIO", aliases: ["GPIOs"], short: "General-purpose input/output: a pin the firmware can read or drive high or low.", detail: "Each GPIO pin has a mode (input, output, alternate function, analogue), an output type (push-pull or open-drain), a speed and pull-up/pull-down settings, all set through registers such as MODER on STM32.", why: "LEDs, buttons and the pins behind every serial bus are GPIOs; you will configure them in almost every firmware task." },
  { id: "alternate-function", term: "alternate function", aliases: ["alternate-function", "AF mode"], short: "A GPIO mode that hands the pin over to a peripheral, such as a UART or I2C port, instead of the firmware driving it directly.", detail: "On STM32 a pin in alternate-function mode is routed to one of several peripherals chosen by the AFR registers. The mode bits for that pin are 10.", why: "A serial port that is silent is often a pin left in input mode instead of alternate function." },
  { id: "interrupt", term: "interrupt", aliases: ["interrupts", "ISR", "interrupt handler", "interrupt service routine"], short: "A hardware event that pauses the main program and runs a small handler function, then resumes.", detail: "Interrupts let the MCU respond immediately to events such as a received byte or a timer tick. The handler is called an ISR (interrupt service routine). Code that the main program and an ISR both touch must be written carefully.", why: "The read-modify-write hazard in the register lesson is exactly the kind of interrupt bug interviewers probe.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "watchdog", term: "watchdog", aliases: ["independent watchdog"], short: "A countdown timer that resets the chip unless firmware keeps refreshing it, so a stuck program cannot hang forever.", detail: "STM32 has an independent watchdog (IWDG) on its own clock and a window watchdog. If the main loop stops refreshing it in time, the chip resets and the cause is recorded in RCC_CSR.", why: "A board that resets itself every second or so is a classic unserviced watchdog, and a classic interview scenario.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "brown-out", term: "brown-out", aliases: ["brown-out detector", "BOR", "brownout"], short: "A dip in the supply voltage below a safe level, which the chip detects and answers with a reset.", detail: "The brown-out reset (BOR) circuit holds the MCU in reset while VDD is below a programmable threshold, so the core never runs on an unsafe voltage. A supply that sags under load causes repeated brown-out resets.", why: "Distinguishing a brown-out from a watchdog reset is a measurement question: scope VDD at the pin.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "program-counter", term: "program counter", aliases: ["PC register", "read the PC", "read PC"], short: "The processor register that holds the address of the instruction being executed.", detail: "When you halt a core with the debugger, the program counter tells you exactly where it is: inside your code, in a wait loop, or in a fault handler.", why: "Halting and reading the program counter is the fastest way to turn 'it hangs' into 'it is stuck here'." },
  { id: "vector-table", term: "vector table", short: "A table at the start of flash listing the initial stack pointer and the addresses of the reset handler and every interrupt handler.", detail: "On reset a Cortex-M core reads the first two words of the vector table to find its stack and its first instruction. If the table is at the wrong address or empty, nothing sensible runs.", why: "Knowing what happens between reset and main() is a standard firmware interview question." },
  { id: "hardfault", term: "hard fault", aliases: ["HardFault", "fault handler"], short: "The processor's response to an illegal operation, such as reading an address that does not exist.", detail: "A Cortex-M hard fault lands execution in the HardFault handler, which in simple firmware is an infinite loop. The stacked registers tell you which instruction caused it.", why: "A board that 'does nothing' but answers the debugger is often sitting in a fault handler." },

  // --- Power, reset, clock, boot ---
  { id: "vdd", term: "VDD", aliases: ["VDDA", "digital supply"], short: "The main supply voltage pin of the chip, typically 3.3 V on an STM32.", detail: "VDD powers the digital logic; VDDA is the analogue supply for the ADC and reference, usually fed from VDD through a filter. Both must be within the datasheet range before anything works.", why: "Measuring VDD at the chip pin, not at the regulator, is the first step of every bring-up.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "vcap", term: "VCAP", aliases: ["VCAP pins", "core regulator"], short: "Pins on STM32F4 parts that expose the internal 1.2 V core regulator and need external capacitors.", detail: "The Cortex-M4 core runs at about 1.2 V produced by a regulator inside the chip. VCAP pins carry that rail out to decoupling capacitors (typically 2.2 µF). If VCAP reads 0 V with VDD present, the core domain is not alive.", why: "VCAP is a quick, decisive measurement that tells you whether the chip itself is dead or merely held in reset.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "ldo", term: "LDO", aliases: ["regulator", "voltage regulator", "low-dropout regulator"], short: "A chip that turns a higher supply, such as 5 V, into a steady lower one, such as 3.3 V.", detail: "A low-dropout (LDO) regulator is linear: simple, quiet, but it dissipates the voltage difference as heat. Its output should be measured under load and at the far end of the trace.", why: "A warm regulator with a sagging output is a sign of a short or overload downstream." },
  { id: "decoupling", term: "decoupling", aliases: ["decoupling capacitor", "decoupling capacitors", "bypass capacitor"], short: "Small capacitors placed right next to a chip's supply pins to supply brief bursts of current and keep the voltage steady.", detail: "Typically 100 nF per supply pin plus a larger bulk capacitor. Missing or badly placed decoupling causes noise, resets and flaky behaviour that is hard to reproduce.", why: "Reviewers look for decoupling first when a schematic is presented." },
  { id: "nrst", term: "NRST", aliases: ["reset pin", "reset line"], short: "The chip's reset pin: active-low, so the core is frozen while it is held at 0 V and runs when it is released high.", detail: "NRST has a weak internal pull-up, so it idles near VDD. A supervisor, the debugger, a push button or a shorted capacitor can pull it low. Short repeated pulses mean the chip keeps resetting itself.", why: "Reading NRST with a meter answers 'no target connected' more often than any other single measurement.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "active-low", term: "active-low", short: "A signal that means 'on' or 'asserted' when it is at 0 V, not when it is high.", detail: "Active-low signals are often named with a leading N or a bar, such as NRST or CS̄. Pulling the line low asserts it; releasing it lets a pull-up bring it high.", why: "Misreading active-low signals leads to inverted logic bugs and wrong conclusions on the bench." },
  { id: "reset-supervisor", term: "reset supervisor", aliases: ["supervisor", "voltage supervisor", "supervisor IC"], short: "A small chip that watches the supply voltage and holds the MCU in reset until the voltage is high enough.", detail: "Supervisors come in variants with different thresholds (for example 3.08 V or 4.63 V), encoded in the part number and the top marking. Fit the wrong variant on a 3.3 V rail and it asserts reset forever.", why: "The 'wrong variant' mission is a realistic production fault; knowing to compare markings with the BOM is a senior habit.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "hsi", term: "HSI", aliases: ["internal oscillator", "internal RC oscillator"], short: "The MCU's built-in clock source (high-speed internal), which runs from reset without any external part.", detail: "On STM32F4 the HSI is a 16 MHz RC oscillator. The chip always starts on it, which is why the debugger works even when the crystal is dead. It is less accurate than a crystal, so firmware often switches to HSE later.", why: "'Does an STM32 need its crystal to boot?' is a common interview question; the answer is no, because of HSI.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "hse", term: "HSE", aliases: ["external crystal", "crystal", "8 MHz crystal", "crystal oscillator"], short: "The external crystal clock source (high-speed external), more accurate than the internal oscillator but off until firmware enables it.", detail: "Firmware turns HSE on and waits for the HSERDY flag before switching to it. If the crystal never starts, that wait loops forever. The oscillator is also off while the chip is in reset.", why: "A silent crystal on a dead board proves nothing; knowing why separates methodical debugging from guesswork.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "boot0", term: "BOOT0", aliases: ["BOOT pins", "boot pin", "boot configuration"], short: "A pin sampled right after reset that chooses where the MCU starts executing: main flash, the built-in bootloader or RAM.", detail: "On STM32F4, BOOT0 low selects main flash. BOOT0 high with BOOT1 low selects the system-memory bootloader. A floating BOOT0 behaves randomly. Some newer families move this into option bits.", why: "A board that runs the bootloader instead of your code is a BOOT0 strap problem, and the debugger still connects.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "bootloader", term: "bootloader", aliases: ["system bootloader", "system memory bootloader", "system-memory bootloader", "ROM bootloader"], short: "A small program stored permanently in the chip that can load new firmware over a serial port or USB.", detail: "The STM32 system bootloader lives in ROM and runs when BOOT0 is high at reset. It is useful for recovery when the application firmware is broken.", why: "Recovering a bricked board through the bootloader is a practical skill employers value." },
  { id: "swd", term: "SWD", aliases: ["debug port", "debug access port", "SWD port"], short: "Serial Wire Debug: the two-pin interface a debugger uses to halt the core, read memory and flash firmware.", detail: "SWD needs the core domain powered, a released reset and the two pins (SWDIO, SWCLK) connected. It does not need the crystal or valid firmware. 'Connect under reset' helps when firmware has reconfigured the pins.", why: "Understanding what SWD needs lets you read 'No target connected' as a short list of possible causes.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "debugger", term: "debugger", aliases: ["ST-LINK", "debug probe"], short: "A tool, such as an ST-LINK, that connects a computer to the chip's debug port to flash, halt and inspect it.", detail: "Through the debugger you can halt the core, read the program counter and registers, set breakpoints and read memory. It is the most informative instrument on the bench once the chip is alive.", why: "Being comfortable halting a core and reading where it is stuck is expected in firmware roles." },
  { id: "rcc", term: "RCC", aliases: ["reset and clock control", "RCC_CSR", "reset-cause flags"], short: "The reset and clock control block: it enables peripheral clocks, selects the system clock and records why the chip last reset.", detail: "RCC registers enable each peripheral's clock (nothing works until it is on), switch between HSI, HSE and PLL, and in RCC_CSR keep flags saying whether the last reset came from the pin, the watchdog, brown-out or software.", why: "Reading the reset-cause flags is the professional answer to 'why does it keep resetting?'", relatedLesson: "mcu-board-does-not-boot" },

  // --- I2C and buses ---
  { id: "i2c", term: "I2C", aliases: ["I²C", "I2C bus"], short: "A two-wire serial bus (data and clock) that lets a controller talk to many small chips such as sensors, each at its own address.", detail: "I2C uses open-drain lines SDA and SCL with pull-up resistors, 7-bit addresses, and an acknowledge bit after every byte. Standard mode runs at 100 kHz, fast mode at 400 kHz.", why: "Sensor interfaces on almost every board are I2C; debugging a silent sensor is a standard interview case.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "sda-scl", term: "SDA", aliases: ["SCL", "SDA/SCL", "SDA and SCL"], short: "The two I2C wires: SDA carries data, SCL carries the clock.", detail: "Both are open-drain and idle high thanks to pull-ups. Data on SDA must be stable while SCL is high; it changes while SCL is low. START and STOP are the exceptions, where SDA changes while SCL is high.", why: "Reading SDA and SCL on a scope is how you prove whether a bus problem is physical, addressing or timing.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "open-drain", term: "open-drain", aliases: ["open drain"], short: "An output that can only pull a line down to 0 V; something else, a pull-up resistor, must raise it.", detail: "Because every device can only pull low, several devices can share one wire safely: the line is high only when nobody pulls it low. This is why I2C needs pull-ups and why a missing pull-up leaves the line stuck at 0 V.", why: "Open-drain is the key to understanding I2C idle levels, bus sharing and why pull-up values matter.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "pull-up", term: "pull-up", aliases: ["pull-ups", "pull-up resistor", "pull-up resistors", "pullup"], short: "A resistor from a signal line to the supply that keeps the line high when nothing is driving it low.", detail: "On I2C, the pull-up value and the bus capacitance set the rise time. Too large a value gives slow, rounded edges; too small makes devices sink more current than they can. Typical values are 2.2 kΩ to 10 kΩ.", why: "Sizing a pull-up from rise time and sink current is a classic design-interview calculation.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "ack-nack", term: "ACK", aliases: ["NACK", "acknowledge", "acknowledge bit", "ACK/NACK", "not acknowledging", "acknowledges", "acknowledged"], short: "After each I2C byte the receiver pulls SDA low for one clock to say 'got it' (ACK). If SDA stays high, that is a NACK.", detail: "A NACK after the address byte means no powered, working device recognised that address. A NACK after a data byte can be normal (a controller ends a read that way).", why: "Being able to say precisely what a NACK proves, and what it does not, is the heart of I2C debugging.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "start-stop", term: "START", aliases: ["STOP", "START condition", "STOP condition"], short: "The special signals that begin and end an I2C transaction: SDA falling while SCL is high (START) and rising while SCL is high (STOP).", detail: "They are the only times SDA changes while SCL is high, which is what makes them recognisable to every device on the bus.", why: "Recognising START and STOP on a capture lets you count bytes and find where a transfer broke.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "seven-bit-address", term: "7-bit address", aliases: ["7-bit", "8-bit address", "address byte", "slave address", "device address"], short: "Each I2C device has a 7-bit address; on the wire it is sent shifted left by one with the read/write bit in the lowest position.", detail: "Address 0x48 becomes 0x90 for a write and 0x91 for a read. Some software libraries take the 7-bit form, others (such as STM32 HAL) the shifted 8-bit form. Mixing them up is the most common I2C firmware bug.", why: "Converting between the two forms correctly, out loud, is a quick interview win.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "clock-stretching", term: "clock stretching", short: "A slow I2C device holding SCL low to make the controller wait until it is ready.", detail: "Controllers must check that SCL has actually risen before counting a clock. Some simple controllers ignore stretching and corrupt data with devices that use it.", why: "Clock stretching explains odd timing failures with some sensors and is a good 'what else could it be' answer." },
  { id: "rise-time", term: "rise time", aliases: ["rise times", "rising edge", "rising edges"], short: "How long a signal takes to go from low to high; on I2C it is set by the pull-up resistor and the wire's capacitance.", detail: "The I2C specification limits rise time to 1000 ns in standard mode and 300 ns in fast mode. Slow edges look like curved 'shark fins' on a scope and can make a receiver sample the wrong level.", why: "Rise time connects a datasheet number to something you can see on the oscilloscope.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "bus-capacitance", term: "bus capacitance", short: "The total stray capacitance of the wires and pins on a bus, which slows every edge.", detail: "Long cables and many devices add capacitance. The I2C specification allows up to 400 pF; beyond that, edges become too slow for the chosen speed.", why: "It is the hidden reason a bus that works on the bench fails on a long cable in the product." },
  { id: "sink-current", term: "sink current", aliases: ["sink", "sink capability", "sinking"], short: "The current a pin can safely pull to ground when it drives a line low.", detail: "I2C devices are only guaranteed to sink 3 mA. If the parallel pull-ups on a bus demand more, the low level creeps up and may no longer be read as 0.", why: "It sets the minimum pull-up value, the other half of the sizing calculation.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "bus-scan", term: "bus scan", aliases: ["I2C bus scan", "address scan"], short: "Firmware that tries every I2C address and lists the ones that acknowledge.", detail: "A scan takes seconds and tells you which devices are alive and where. It is the quickest way to spot an address-strap mismatch.", why: "Mentioning a bus scan early in an I2C debugging answer signals real bench experience.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "address-pin", term: "ADD0", aliases: ["address pin", "address pins", "address strap", "strapped"], short: "A pin on a sensor that is tied high or low (strapped) to choose which I2C address the sensor uses.", detail: "The TMP102, for example, uses 0x48 with ADD0 to ground and 0x49 with ADD0 to V+. The datasheet table is the only authority on the mapping.", why: "Strap mismatches between schematic notes and firmware are a realistic production fault.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "uart", term: "UART", aliases: ["serial port", "debug UART"], short: "A simple two-wire serial link (transmit and receive) used for consoles, logs and talking to modules.", detail: "UART has no clock wire; both ends agree on a baud rate. Framing errors usually mean a baud mismatch or a bad ground.", why: "A UART log is often the first sign of life from a board and a basic interview topic." },
  { id: "spi", term: "SPI", short: "A fast four-wire serial bus (clock, data out, data in, chip select) used for displays, flash memories and sensors.", detail: "SPI has no addresses; each device has its own chip-select line. Clock polarity and phase (the 'mode') must match on both sides.", why: "SPI mode mismatches are a classic 'first byte is garbage' interview scenario." },
  { id: "can", term: "CAN", aliases: ["CAN bus"], short: "A robust two-wire bus used in vehicles and industrial systems, where messages carry identifiers rather than addresses.", detail: "CAN arbitrates between senders by identifier priority and has built-in error counting; a node that errors too often goes 'bus-off'.", why: "Automotive and aerospace roles expect at least conceptual CAN knowledge." },

  // --- Embedded C ---
  { id: "bit-mask", term: "bit mask", aliases: ["mask", "masks", "bit masks"], short: "A number with 1s in exactly the bit positions you want to affect, used with AND, OR and NOT to change only those bits.", detail: "Set with reg |= mask, clear with reg &= ~mask, test with (reg & mask). Build masks from positions, for example (1u << 5), and keep them unsigned.", why: "Masks are the daily bread of register-level C and appear in nearly every embedded coding interview.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "bit-field", term: "bit field", aliases: ["field", "fields", "bit fields", "multi-bit field"], short: "A group of neighbouring bits inside a register that together hold one setting, such as a pin's mode.", detail: "A field is described by its position and width. Writing it means clearing the field with its mask and ORing in the new value shifted to the position. Vendor headers provide _Pos and _Msk constants for each field.", why: "Field writes done wrong silently change other settings; doing them right is what reviewers look for.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "volatile", term: "volatile", short: "A C keyword telling the compiler a value can change outside the program's control, so every read and write must really happen.", detail: "Hardware registers must be volatile, otherwise the compiler may cache a value or delete a write it thinks is redundant. Volatile does not make operations atomic and does not wait for hardware.", why: "'What does volatile do?' is asked in almost every embedded C interview; the precise answer is short.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "rmw", term: "read-modify-write", aliases: ["read–modify–write", "RMW"], short: "Changing some bits of a register by reading it, altering the copy, and writing it back; three steps that can be interrupted.", detail: "If an interrupt changes the same register between the read and the write, the write-back overwrites the interrupt's change. Set/reset registers, critical sections or exclusive-access instructions avoid the problem.", why: "Explaining the lost-update window is the classic follow-up to the volatile question.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "atomic", term: "atomic", aliases: ["atomicity"], short: "An operation that completes as a single, uninterruptible step, so nothing can see or change the value halfway through.", detail: "A single 32-bit store is atomic on Cortex-M; a compound assignment such as |= is not. Hardware set/reset registers give atomic bit changes with one store.", why: "Knowing what is and is not atomic separates correct interrupt-safe code from code that works by luck.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "critical-section", term: "critical section", short: "A short stretch of code run with interrupts disabled so it cannot be interrupted halfway.", detail: "Entering a critical section saves the interrupt state and disables interrupts; leaving restores it. Keep them very short to avoid delaying real-time responses.", why: "It is the general-purpose answer when no atomic hardware register exists." },
  { id: "ldrex-strex", term: "LDREX/STREX", aliases: ["exclusive access", "exclusive-access instructions"], short: "Cortex-M instructions that read a value and later store it only if nothing touched the location in between, retrying otherwise.", detail: "They implement lock-free atomic updates without disabling interrupts, and underpin RTOS primitives such as mutexes.", why: "A good 'bonus' answer to the read-modify-write question." },
  { id: "bsrr", term: "BSRR", aliases: ["set/reset register", "set/reset registers", "bit set/reset register"], short: "An STM32 GPIO register where writing a 1 sets or resets a pin in one store, with no read, so it cannot be interrupted halfway.", detail: "Bits 0–15 set pins; bits 16–31 reset them; zeros do nothing. It avoids the read-modify-write hazard on the output data register (ODR).", why: "Knowing BSRR exists is how you show you have actually written STM32 GPIO code.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "w1c", term: "write-1-to-clear", aliases: ["W1C", "rc_w0", "rc_w1"], short: "A kind of status flag that is cleared by writing a 1 to it, not a 0, so the usual |= pattern clears more flags than you meant to.", detail: "Reference manuals mark each bit's behaviour (rc_w1 for write-1-to-clear, rc_w0 for write-0-to-clear). Write the register directly with exactly the pattern the hardware expects.", why: "It is a subtle, real bug class that interviewers use to test whether you read register descriptions.", relatedLesson: "embedded-c-register-bit-masks" },
  { id: "undefined-behaviour", term: "undefined behaviour", aliases: ["undefined behavior", "UB"], short: "Code the C standard gives no meaning to; the compiler may do anything, including something that works today and breaks tomorrow.", detail: "Shifting a signed int into its sign bit, such as 1 << 31, is undefined behaviour. Use unsigned literals (1u << 31) for masks.", why: "Spotting undefined behaviour in a code snippet is a common interview exercise." },
  { id: "cmsis", term: "CMSIS", short: "Arm's standard set of headers and functions for Cortex-M chips, including register definitions and helpers such as __DSB().", detail: "Vendor headers built on CMSIS give you the structs and the _Pos/_Msk constants for every register, so code says which field it means.", why: "Using the named constants instead of magic numbers is what reviewers expect." },
  { id: "memory-barrier", term: "memory barrier", aliases: ["__DSB()", "barrier", "DSB"], short: "An instruction that makes the processor finish all pending memory accesses before continuing.", detail: "After writing a register whose effect must be complete before the next step (for example enabling a clock), a data synchronisation barrier or a read-back ensures the order.", why: "It is the right answer to 'does volatile wait for the hardware?' (it does not)." },

  // --- Bench and process ---
  { id: "oscilloscope", term: "oscilloscope", aliases: ["scope", "on the scope"], short: "An instrument that draws voltage against time, so you can see pulses, edges and noise that a meter averages away.", detail: "Use it to see reset pulses, clock activity and bus waveforms. Probe capacitance can disturb sensitive nodes such as crystal pins; use a 10x probe and a short ground.", why: "Saying what you would look at on a scope, and what you expect to see, is how engineers prove a hypothesis." },
  { id: "logic-analyser", term: "logic analyser", aliases: ["logic analyzer", "analyser"], short: "An instrument that records digital signals and decodes buses such as I2C, showing addresses, data and ACK/NACK bits.", detail: "Cheaper than a scope for digital work and far better for decoding. A capture of one failing transaction usually settles whether the problem is physical, addressing or timing.", why: "'Capture one transaction first' is a hallmark of experienced embedded debugging.", relatedLesson: "i2c-sensor-not-acknowledging" },
  { id: "multimeter", term: "multimeter", aliases: ["meter", "DMM", "with a meter"], short: "The basic bench instrument for measuring voltage, resistance and current.", detail: "A multimeter gives an average reading; it cannot show pulses. It is the right first tool for supply voltages, idle levels and continuity checks.", why: "Most bring-up faults are found with a meter before any firmware is touched." },
  { id: "bench-supply", term: "bench supply", aliases: ["bench PSU", "bench power supply"], short: "An adjustable laboratory power supply with a current limit you can set.", detail: "Setting a low current limit protects a new board: a short shows as the supply hitting its limit rather than as smoke.", why: "Mentioning current-limited bring-up shows production awareness." },
  { id: "bom", term: "BOM", aliases: ["bill of materials"], short: "The bill of materials: the list of every part on a board, with exact part numbers.", detail: "When a part's marking does not match the BOM, the wrong variant may have been fitted. Comparing markings against the BOM is a standard incoming-inspection step.", why: "The supervisor-variant mission is exactly a BOM-versus-marking problem." },
  { id: "datasheet", term: "datasheet", aliases: ["datasheets"], short: "The manufacturer's document for a part: pins, limits, timing, address tables and marking codes.", detail: "The datasheet is the authority. Schematic comments and forum posts are not. Address tables, threshold variants and absolute maximum ratings all live here.", why: "Interviewers notice whether you reason from the datasheet or from memory." },
  { id: "reference-manual", term: "reference manual", aliases: ["RM0090"], short: "The long document describing every register of an MCU family, such as RM0090 for STM32F4.", detail: "Where the datasheet gives electrical limits, the reference manual gives register maps, bit meanings and access types (read-only, write-1-to-clear and so on).", why: "Being able to find a register's description quickly is a real on-the-job skill." },
  { id: "schematic", term: "schematic", short: "The drawing of a circuit showing every component and how they connect.", detail: "Reading a schematic means following power rails, finding pull-ups and straps, and checking notes against the datasheet. Notes can be wrong; wires cannot.", why: "Schematic reading is tested in most hardware-adjacent interviews." },
  { id: "rework", term: "rework", aliases: ["hot-air rework", "hot air"], short: "Physically changing an assembled board: lifting a pin, swapping a part, adding a wire.", detail: "Rework takes time, risks damage and destroys evidence. It belongs after a hypothesis, not before.", why: "Choosing a measurement over rework is a sign of engineering judgement." },
  { id: "bring-up", term: "bring-up", aliases: ["board bring-up"], short: "The first power-on and step-by-step checkout of a newly built board.", detail: "Bring-up follows an order: visual inspection, power, reset, clock, debugger, then firmware. Each step is chosen because it is cheap and eliminates many causes.", why: "'Walk me through bring-up' is one of the most common hardware/firmware interview questions.", relatedLesson: "mcu-board-does-not-boot" },
  { id: "ferrite-bead", term: "ferrite bead", short: "A small component that blocks high-frequency noise on a supply line while passing DC.", detail: "Often placed between VDD and VDDA. A cracked or wrong bead can drop voltage under load and starve the analogue supply.", why: "A plausible 'why is VDDA lower than VDD?' answer." },
  { id: "zero-ohm-link", term: "0 Ω link", aliases: ["0 Ω jumper", "zero-ohm link", "solder jumper"], short: "A resistor with no resistance, used as a removable wire to select options on a board, such as an address strap.", detail: "Moving a 0 Ω link changes a strap without redesigning the board. Its position must match what the firmware assumes.", why: "Straps and links are where schematic notes and reality most often disagree." },
  // --- UART ---
  { id: "baud", term: "baud rate", aliases: ["baud", "bits per second"], short: "How many bits per second a serial link sends; both ends must agree on it.", detail: "At 115 200 baud each bit lasts 8.68 µs. UART has no clock wire, so a mismatch between sender and receiver of more than a few percent corrupts the data.", why: "Measuring one bit on a scope and converting it to baud is the fastest way to diagnose a garbled console.", relatedLesson: "uart-framing-and-baud" },
  { id: "start-bit", term: "start bit", aliases: ["stop bit", "stop bits", "framing bit"], short: "The low bit that begins a UART frame; the high stop bit ends it.", detail: "The line idles high. The start bit's falling edge lets the receiver synchronise; the stop bit guarantees an idle period before the next frame. A stop bit sampled low is a framing error.", why: "Knowing which bits are framing bits and which are data is essential to decoding a capture.", relatedLesson: "uart-framing-and-baud" },
  { id: "parity", term: "parity", aliases: ["parity bit", "even parity", "odd parity"], short: "An optional one-bit checksum in a UART frame that makes the number of 1s even or odd.", detail: "Parity catches single-bit errors only. '8N1' means 8 data bits, no parity, 1 stop bit; '7E1' means 7 data bits with even parity.", why: "A parity-setting mismatch produces garbage at the right baud rate, a symptom worth recognising.", relatedLesson: "uart-framing-and-baud" },
  { id: "framing-error", term: "framing error", short: "A receiver's report that the stop bit was not high where expected, meaning the timing or format is wrong.", detail: "Caused by baud mismatch, wrong frame format, noise, or a break condition. STM32 USARTs set the FE flag in the status register.", why: "Reading the error flags tells you whether garbage is a rate problem or a noise problem.", relatedLesson: "uart-framing-and-baud" },
  { id: "lsb-first", term: "LSB first", aliases: ["least-significant bit first", "MSB first", "most-significant first"], short: "The order bits are sent on a serial line: UART sends the least significant bit first, SPI usually the most significant first.", detail: "Decoding a UART capture means reading the data bits backwards; decoding SPI usually means reading them forwards. Getting this wrong bit-reverses every byte.", why: "A bit-reversed value in a capture is an instant clue to which convention you have assumed wrongly." },
  { id: "rs232", term: "RS-232", aliases: ["RS232", "TIA-232"], short: "The old serial standard that uses ±3 V to ±15 V signalling with inverted logic, unlike 3.3 V logic-level UART.", detail: "Connecting an RS-232 port to a logic-level UART pin needs a transceiver (level shifter) such as a MAX3232. Direct connection gives nonsense and can damage the pin.", why: "'Serial port' can mean either; checking which before plugging in prevents a dead pin.", relatedLesson: "uart-framing-and-baud" },
  { id: "usb-uart", term: "USB-to-UART adapter", aliases: ["USB-to-serial adapter", "USB-UART", "serial adapter"], short: "A small device that gives a computer a logic-level serial port, used for debug consoles.", detail: "Most are 3.3 V logic level; some are 5 V or RS-232. TX on the adapter connects to RX on the board and vice versa, and ground must be shared.", why: "It is the first tool connected to a new board, so its level and wiring are the first things to check." },

  // --- Clocks ---
  { id: "hse-value", term: "HSE_VALUE", aliases: ["clock configuration", "clock tree", "SystemCoreClock"], short: "The firmware's constant for the external crystal frequency, from which every other clock is computed.", detail: "If HSE_VALUE says 8 MHz but the board has 25 MHz, the PLL settings produce clocks 3.125× too fast, and baud rates, timers and delays all scale by the same ratio. SystemCoreClock is the firmware's resulting belief about the core frequency.", why: "A single wrong constant inherited from an evaluation board is a classic bring-up fault.", relatedLesson: "uart-framing-and-baud" },
  { id: "lsi", term: "LSI", aliases: ["low-speed internal oscillator", "32 kHz"], short: "The MCU's slow internal RC oscillator, nominally 32 kHz, that clocks the independent watchdog and the RTC.", detail: "It is imprecise: the STM32F4 datasheet allows 17 kHz to 47 kHz. Watchdog timeouts computed from the nominal value need margin for this range.", why: "LSI tolerance is why a watchdog timeout that looks like 1.0 s may really be 0.7 s or 1.9 s.", relatedLesson: "watchdogs-and-reset-loops" },
  { id: "prescaler", term: "prescaler", aliases: ["clock divider", "reload value"], short: "A divider that slows a clock before it reaches a counter; the reload value is where the counter starts counting down.", detail: "For the IWDG, timeout = prescaler × (reload + 1) ÷ f_LSI. Prescaler codes select ÷4 to ÷256 and the reload register holds 0 to 4095.", why: "Sizing any timer, watchdog or baud generator is prescaler arithmetic.", relatedLesson: "watchdogs-and-reset-loops" },
  { id: "iwdg", term: "IWDG", aliases: ["window watchdog", "WWDG"], short: "STM32's independent watchdog, clocked by the LSI; the window watchdog (WWDG) is its bus-clocked cousin that must be refreshed inside a time window.", detail: "The IWDG cannot be stopped once started. The WWDG resets the chip if refreshed too early as well as too late, catching code that runs but does no useful work.", why: "Knowing which watchdog does what is expected in any firmware interview.", relatedLesson: "watchdogs-and-reset-loops" },
  { id: "reset-cause", term: "reset cause", aliases: ["reset source", "RCC_CSR flags", "IWDGRSTF", "BORRSTF"], short: "The flags an MCU keeps to say why it last reset: watchdog, brown-out, pin, software or power-on.", detail: "On STM32F4 they live in RCC_CSR and stay set until cleared with RMVF. Reading them at startup turns 'it rebooted' into 'the watchdog fired'.", why: "Reading these flags before forming a theory is the fastest route through any reset investigation.", relatedLesson: "watchdogs-and-reset-loops" },

  // --- SPI ---
  { id: "spi-mode", term: "SPI mode", aliases: ["CPOL", "CPHA", "clock polarity", "clock phase", "mode 0", "mode 3"], short: "One of four conventions for which clock edge carries the data: CPOL sets the clock's idle level, CPHA chooses the first or second edge for sampling.", detail: "Mode 0 (CPOL 0, CPHA 0) and mode 3 (CPOL 1, CPHA 1) both sample on the rising edge and cover most devices. A mismatch shifts received data by one bit.", why: "Translating a datasheet's timing wording into CPOL/CPHA is a standard interview exercise.", relatedLesson: "spi-modes-and-chip-select" },
  { id: "chip-select", term: "chip select", aliases: ["CS", "NSS", "slave select", "SS"], short: "The active-low line that tells one SPI device the clocks are meant for it.", detail: "Most devices reset their bit counter on CS falling and commit on CS rising, so holding CS low across a multi-byte transfer and releasing it between transactions is part of the protocol. STM32 users usually drive it from a GPIO.", why: "Wrong CS framing gives 'correct on the second read' and other confusing symptoms.", relatedLesson: "spi-modes-and-chip-select" },
  { id: "miso-mosi", term: "MISO", aliases: ["MOSI", "SCK", "COPI", "CIPO", "SDI", "SDO"], short: "The SPI data lines: MOSI carries master-to-slave data, MISO slave-to-master; SCK is the clock the master always drives.", detail: "Newer names are COPI and CIPO; device datasheets often say SDI and SDO from the device's point of view. All slaves share MOSI, MISO and SCK and have their own chip select.", why: "Mis-wiring SDI/SDO naming is a common reason MISO reads a constant 0xFF.", relatedLesson: "spi-modes-and-chip-select" },
  { id: "shift-register", term: "shift register", short: "A chain of flip-flops that moves bits along one position per clock; SPI is two of them joined in a ring.", detail: "Every SPI clock shifts one bit out of the master and one out of the slave simultaneously, which is why every transfer is both a write and a read.", why: "Understanding SPI as shift registers explains dummy bytes and full-duplex behaviour." },
  { id: "dummy-byte", term: "dummy byte", aliases: ["dummy bytes", "dummy clocks"], short: "A meaningless byte the SPI master sends only to generate the clocks a slave needs to send its reply.", detail: "A slave cannot drive MISO without clocks. To read N bytes after a command, the master transmits N dummy bytes and collects what arrives on MISO.", why: "Forgetting dummy bytes is why a 'read' returns nothing on SPI.", relatedLesson: "spi-modes-and-chip-select" },

  // --- Integers ---
  { id: "integer-promotion", term: "integer promotion", aliases: ["promoted to int", "promotion"], short: "C's rule that values narrower than int are converted to int before arithmetic.", detail: "uint8_t a = 200, b = 100; a + b is computed as int 300. Storing it back into a uint8_t truncates to 44, but a comparison on the expression sees 300. On Cortex-M, int is 32 bits.", why: "Most surprising results with small types come from promotion; reviewers ask 'what width is this computed in?'", relatedLesson: "fixed-width-integers-overflow-shifts" },
  { id: "wrap-around", term: "wrap-around", aliases: ["wraps", "modulo 2^N", "overflow", "wrap"], short: "What unsigned arithmetic does when a result does not fit: it keeps only the low bits, counting round like an odometer.", detail: "For a uint8_t, 250 + 10 = 4. This is defined behaviour for unsigned types. For signed types, overflow is undefined and the compiler may assume it never happens.", why: "Wrap-safe elapsed-time code depends on unsigned wrap being defined.", relatedLesson: "fixed-width-integers-overflow-shifts" },
  { id: "fixed-width-types", term: "fixed-width types", aliases: ["uint8_t", "uint16_t", "uint32_t", "int32_t", "stdint.h"], short: "Integer types with a guaranteed size from <stdint.h>, such as uint8_t (8 bits) and uint32_t (32 bits).", detail: "Plain int and long vary between platforms; fixed-width types say exactly how many bits you have, which is what hardware registers and protocols require.", why: "Using them is a basic expectation in embedded code review.", relatedLesson: "fixed-width-integers-overflow-shifts" },
  { id: "tick-counter", term: "tick counter", aliases: ["HAL_GetTick", "SysTick", "free-running timer"], short: "A counter that increments at a fixed rate, often every millisecond, used to measure time in firmware.", detail: "A 32-bit millisecond counter wraps after about 49.7 days; a 16-bit timer counter wraps every 65 536 ticks. Correct code compares the unsigned difference between two readings rather than absolute values.", why: "Counter wrap bugs survive every bench test and fail weeks later in the field.", relatedLesson: "fixed-width-integers-overflow-shifts" },

  // --- Instrumentation ---
  { id: "probe-10x", term: "10× probe", aliases: ["10x probe", "passive probe", "1× probe", "1x probe"], short: "The standard oscilloscope probe: a 9 MΩ tip resistor forming a 10:1 divider with the scope's 1 MΩ input, presenting only 10 to 15 pF to the circuit.", detail: "A 1× probe has no divider and loads the node with around 100 pF. The 10× probe must be compensated so its division is correct at all frequencies.", why: "Choosing the probe, and knowing what it adds, is the first decision in any measurement.", relatedLesson: "oscilloscope-probing" },
  { id: "probe-compensation", term: "probe compensation", aliases: ["compensated", "compensate the probe", "calibration square wave"], short: "Adjusting a small capacitor in a 10× probe so its divider ratio is the same at all frequencies, checked against the scope's calibration square wave.", detail: "Under-compensated probes round off edges; over-compensated ones add overshoot. Both produce false edge measurements.", why: "An uncompensated probe makes every rise-time and overshoot reading wrong.", relatedLesson: "oscilloscope-probing" },
  { id: "ground-lead", term: "ground lead", aliases: ["ground clip", "alligator ground", "spring ground tip", "spring ground"], short: "The probe's return connection; the long alligator lead adds inductance that rings with the probe's capacitance, so fast edges need the short spring tip.", detail: "The ground lead is also connected to mains earth through the scope; clipping it to a node that is not at ground potential shorts that node to earth.", why: "Ground-lead resonance is the commonest fake signal-integrity problem on a scope screen.", relatedLesson: "oscilloscope-probing" },
  { id: "bandwidth", term: "bandwidth", aliases: ["scope bandwidth", "bandwidth limit"], short: "The frequency at which an oscilloscope attenuates a sine wave by 3 dB; it sets the fastest edge the scope can show.", detail: "Rise time ≈ 0.35 ÷ bandwidth for a classic response: a 100 MHz scope shows no edge faster than about 3.5 ns. A bandwidth of five times the signal's highest frequency of interest is the usual rule.", why: "Measuring an edge near the scope's own rise time tells you about the scope, not the circuit.", relatedLesson: "oscilloscope-probing" },
  { id: "sample-rate", term: "sample rate", aliases: ["samples per second", "MS/s", "memory depth"], short: "How many points per second a digital scope records; it falls at long timebases because memory depth is fixed.", detail: "Fewer than two samples per signal period causes aliasing. Several samples per period are needed to see a waveform's shape.", why: "Long-timebase captures of fast signals quietly alias unless you check.", relatedLesson: "oscilloscope-probing" },
  { id: "aliasing", term: "aliasing", aliases: ["alias", "Nyquist"], short: "A false, slower waveform a digital scope shows when it samples a signal fewer than twice per period (the Nyquist limit).", detail: "The alias looks real. Prove it by changing the timebase: a genuine signal keeps its frequency, an alias changes. The apparent frequency is the distance from the signal frequency to the nearest multiple of the sample rate.", why: "Aliasing fools engineers into chasing oscillations that do not exist.", relatedLesson: "oscilloscope-probing" },
  { id: "single-shot", term: "single-shot capture", aliases: ["single shot", "edge trigger", "trigger"], short: "Setting the scope to capture one event when a chosen signal crosses a level, instead of continuously redrawing.", detail: "Triggering on the symptom (NRST falling, a fault line asserting) with pre-trigger memory shows what happened just before the event.", why: "One-off faults such as a reset pulse are only caught this way.", relatedLesson: "oscilloscope-probing" },
  { id: "differential-probe", term: "differential probe", aliases: ["active probe", "isolated probe"], short: "A probe that measures the voltage between two nodes without connecting either to earth; active probes also present very low capacitance.", detail: "Required for any node not at ground potential, such as mains-referenced or patient-isolated circuits, and for fast signals where a passive probe's loading is too much.", why: "Knowing when a passive probe is unsafe or inadequate is part of bench competence.", relatedLesson: "oscilloscope-probing" },
  { id: "ac-coupling", term: "AC coupling", aliases: ["DC coupling", "ripple"], short: "A scope input setting that removes the DC level so small ripple on a supply rail can be seen at high sensitivity.", detail: "Pair it with the 20 MHz bandwidth limit to keep high-frequency pickup from hiding the real ripple, and keep the ground loop tiny.", why: "Measuring supply ripple properly is a routine bench task with several ways to get it wrong.", relatedLesson: "oscilloscope-probing" },

  // --- Integration and verification ---
  { id: "icd", term: "interface control document", aliases: ["ICD", "interface document", "interface control documents"], short: "The written contract between two sides of an interface: electrical, timing, framing, data representation and error behaviour.", detail: "For each data field it states width, byte order, signedness, scaling with units, valid range and the invalid-value code. Both teams implement to it, and the side that departs from it is the one that changes.", why: "Most integration failures are a missing line in the ICD, not a broken board.", relatedLesson: "interface-control-and-integration-faults" },
  { id: "byte-order", term: "byte order", aliases: ["endianness", "big-endian", "little-endian", "endian"], short: "Which byte of a multi-byte value is sent or stored first: big-endian sends the most significant byte first, little-endian the least.", detail: "0x09C4 is 09 C4 big-endian and C4 09 little-endian. Reading one as the other turns 25.00 °C into 501.85 °C, a structured, reproducible wrong number.", why: "A byte-swap has an unmistakable signature once you know to look for it.", relatedLesson: "interface-control-and-integration-faults" },
  { id: "signedness", term: "signedness", aliases: ["two's complement", "signed", "unsigned"], short: "Whether a field can represent negative numbers; two's complement is the usual encoding, where 0xFFE6 as a 16-bit signed value is −26.", detail: "Reading a signed field as unsigned turns −26 into 65 510. Negative and boundary values are where sign errors show, which is why golden frames include them.", why: "Temperature, current and position fields are signed; the bug appears the first cold day.", relatedLesson: "interface-control-and-integration-faults" },
  { id: "scaling", term: "scaling", aliases: ["scale factor", "LSB value", "per LSB", "units mismatch"], short: "The physical value represented by one count of a field, with its units, such as 0.01 °C per LSB, sometimes with an offset.", detail: "A scaling or units mismatch gives values wrong by a constant factor or offset (×10, ×4.45, −273). The Mars Climate Orbiter was lost to a pound-force versus newton mismatch across a documented interface.", why: "Send a known reference value and compute the ratio: a one-measurement test for scaling.", relatedLesson: "interface-control-and-integration-faults" },
  { id: "crc", term: "CRC", aliases: ["checksum", "cyclic redundancy check", "CRC-16"], short: "A check value computed from a frame's bytes so the receiver can detect corruption in transit.", detail: "The ICD must state the polynomial, initial value and which bytes are covered. A passing CRC proves the bytes arrived as sent, so a wrong value with a good CRC is an interpretation fault, not a link fault.", why: "Reading a passing CRC as evidence saves hours of chasing noise and termination.", relatedLesson: "interface-control-and-integration-faults" },
  { id: "golden-frame", term: "golden frame", aliases: ["golden vector", "golden message", "golden frames"], short: "A byte sequence taken from the interface document with known field values, used as a test input to prove a parser or encoder follows the contract.", detail: "Include nominal, negative, boundary and invalid-code values. Pair golden frames with a physical reference measured across the real link.", why: "Golden-frame tests make a byte-order or sign fault impossible to reintroduce silently.", relatedLesson: "interface-control-and-integration-faults" },
  { id: "rs485", term: "RS-485", aliases: ["RS485", "differential bus"], short: "A differential serial link standard for longer cables and noisy environments, needing termination at both ends and bias resistors.", detail: "The UART framing rides on top; RS-485 only defines the electrical layer. Termination is typically 120 Ω at each end of the cable.", why: "Industrial links are mostly RS-485 (Modbus RTU); knowing it is a physical layer, not a protocol, avoids confusion." },
  { id: "requirement", term: "requirement", aliases: ["requirements", "REQ"], short: "A statement of what the product shall do, written so that a test can show whether it does: a quantity, a condition and a way to measure it.", detail: "'Shall respond quickly' is not a requirement; 'shall assert ALARM within 2.0 s of a sensor fault, measured from the sensor-line event to the ALARM edge' is. The limit comes from a hazard analysis or a customer need, never from what the design happens to do.", why: "Untestable requirements are the most common defect a verification engineer finds.", relatedLesson: "writing-a-trustworthy-test-case" },
  { id: "test-case", term: "test case", aliases: ["test procedure", "TC-"], short: "A written, repeatable check with an identifier, a trace to a requirement, preconditions, steps, an expected result with a method, a pass criterion and a record.", detail: "The expected result must be something an instrument shows, with a tolerance, so two testers get the same verdict. 'Pass' is not an expected result.", why: "Reviewers judge test cases by whether they can fail.", relatedLesson: "writing-a-trustworthy-test-case" },
  { id: "traceability", term: "traceability", aliases: ["traceability matrix", "trace", "traced"], short: "The recorded links from hazards to requirements to tests, so every requirement has a test and every test has a reason.", detail: "A traceability matrix exposes gaps (requirements with no test) and orphans (tests with no requirement), and maps a failed test to the requirement and impact it affects.", why: "Safety standards in every regulated industry require it; the matrix is what an auditor opens first.", relatedLesson: "writing-a-trustworthy-test-case" },
  { id: "verification", term: "verification", aliases: ["validation", "verify", "validate", "V&V"], short: "Verification asks 'did we build it right?' (does the product meet its requirements); validation asks 'did we build the right thing?' (does it meet the need).", detail: "A perfectly verified wrong requirement still fails validation. Test levels, unit, integration, system and regression, are all verification activities.", why: "Interviewers ask the difference to see whether you understand what a passing test proves.", relatedLesson: "writing-a-trustworthy-test-case" },
  { id: "regression-test", term: "regression test", aliases: ["regression", "regression testing", "unit test", "integration test", "system test"], short: "Re-running earlier tests after a change to prove nothing that used to work has broken; one of the test levels alongside unit, integration and system.", detail: "Unit tests isolate a function; integration tests join two parts; system tests check the whole product against requirements; regression re-runs any of them after a change.", why: "Knowing which level a test belongs to tells you what a failure means.", relatedLesson: "writing-a-trustworthy-test-case" },
  { id: "fault-injection", term: "fault injection", aliases: ["inject a fault", "injected faults", "fault-injection"], short: "Deliberately causing a fault (open a sensor, corrupt a frame, dip the supply) to test that the system detects and handles it.", detail: "It is the negative half of verification: it proves the detection path and the test method can see a failure, not only a success.", why: "Safety standards require it for safety mechanisms, and it is where most field failures would have been found.", relatedLesson: "writing-a-trustworthy-test-case" },
  { id: "hazard-analysis", term: "hazard analysis", aliases: ["hazard", "safety analysis", "risk analysis"], short: "The study of what can go wrong, how badly, and what the product must do about it; the source of safety-relevant requirement limits.", detail: "A limit such as 'alarm within 2 s' is derived from how fast the process can become dangerous, which the hazard analysis states. Requirements derived from measurements of the design instead are backwards.", why: "Knowing where a number comes from is what separates a verification engineer from a tester." },
  { id: "root-cause", term: "root cause", aliases: ["root causes", "root-cause", "root-cause analysis", "RCA"], short: "The earliest changeable condition in a chain of causes whose correction makes the symptom impossible for the whole class of failure.", detail: "Tests: fixing it removes the symptom rather than making it rarer; it is a condition, not a person; fixing it prevents the class. The five whys stop at the first condition you can change and verify.", why: "Every mission in the academy ends by naming one; interviews ask you to tell the story of finding one.", relatedLesson: "root-cause-analysis" },
  { id: "five-whys", term: "five whys", aliases: ["5 whys", "cause-and-effect diagram", "fishbone", "Ishikawa"], short: "Asking 'why' of each answer until a changeable condition is reached; the cause-and-effect (fishbone) diagram keeps the branches honest by category.", detail: "Categories: design, component, process, environment, firmware, measurement. Stopping early (at the watchdog) or going too far (at 'time pressure') are the two failure modes.", why: "Simple tools that reviewers recognise; the discipline is in where you stop.", relatedLesson: "root-cause-analysis" },
  { id: "corrective-preventive", term: "corrective action", aliases: ["preventive action", "corrective and preventive", "CAPA"], short: "A corrective action fixes the affected units; a preventive action changes the condition, adds detection or changes the process so the failure class cannot recur.", detail: "A write-up with only corrective actions is a repair report. Reviews expect at least one of each, plus a verification with a measured rate afterwards.", why: "The distinction is what makes a root-cause analysis worth the name.", relatedLesson: "root-cause-analysis" },
  { id: "fault-tree", term: "fault tree", aliases: ["fault tree analysis", "FTA", "top event"], short: "A diagram that starts from a failure (the top event) and shows which combinations of lower events, through AND and OR gates, can cause it.", detail: "Used qualitatively here: each leaf is something you can measure or inject, and AND gates explain why intermittent faults are intermittent (two conditions must coincide).", why: "Turns 'it happens sometimes' into a list of experiments.", relatedLesson: "root-cause-analysis" },
  { id: "current-limit", term: "current limit", aliases: ["constant-current mode", "CC mode", "current-limited"], short: "The maximum current a bench supply will deliver; above it the supply drops its voltage instead, so a short becomes a reading rather than smoke.", detail: "Set it from the expected current plus margin for inrush, often about twice steady state to begin with. When the supply shows constant-current mode at power-up, the board draws more than designed: stop and find out why.", why: "The first-power step every bring-up checklist starts with.", relatedLesson: "board-bring-up-checklist" },
  { id: "rail-resistance", term: "rail-to-ground resistance", aliases: ["resistance to ground", "short check", "pre-power check"], short: "Measuring the resistance between an unpowered supply rail and ground to catch shorts before the first power-up.", detail: "A healthy small-board rail reads hundreds of ohms to tens of kilohms; below about 10 Ω is a short (bridge, reversed or failed capacitor, wrong part). Localise it unpowered.", why: "Minutes of measurement that save a regulator, a board and an afternoon.", relatedLesson: "board-bring-up-checklist" },
  { id: "first-article", term: "first article", aliases: ["first-article", "first unit"], short: "The first unit of a new design or build to come off assembly, inspected and brought up more carefully than production units because nothing about it has been proven yet.", detail: "Its bring-up checklist becomes the build's birth certificate and the basis of the production test.", why: "Vocabulary every integration and test role uses." },
  // --- Firmware architecture, RTOS, Linux ---
  { id: "reset-handler", term: "reset handler", aliases: ["Reset_Handler", "startup code"], short: "The first code to run after reset: copies .data from flash to RAM, zeroes .bss, calls SystemInit, runs constructors, calls main.", detail: "Skipping it (for example a bootloader jumping to main) leaves globals uninitialised, the vector table pointing at the wrong image and the clock unconfigured.", why: "Three classic pre-main faults are this handler's steps, skipped.", relatedLesson: "from-reset-vector-to-main" },
  { id: "data-bss", term: "data and bss sections", aliases: [".data", ".bss", "linker script"], short: ".data holds initialised globals (values stored in flash, copied to RAM at startup); .bss holds zero- and un-initialised globals (no flash space, zeroed at startup). The linker script places both and defines the symbols the startup loop uses.", detail: "A global that reads garbage at the top of main means the .bss loop never ran; a global with a wrong initial value means the .data copy or the linker addresses are wrong.", why: "Where a global's initial value comes from is a standard firmware question.", relatedLesson: "from-reset-vector-to-main" },
  { id: "vtor", term: "VTOR", aliases: ["Vector Table Offset Register", "vector table offset"], short: "The Cortex-M register that tells the core where the active vector table is; it resets to 0 and must be set by any image that does not live at the boot address.", detail: "After a bootloader jump, interrupts use whatever table VTOR points at. Left unset, they run the bootloader's handlers.", why: "The usual reason interrupts break after a bootloader jump.", relatedLesson: "from-reset-vector-to-main" },
  { id: "systeminit", term: "SystemInit", aliases: ["system init", "clock configuration at startup"], short: "The vendor function called by the reset handler that configures the clock tree (HSI to PLL), enables the FPU and sets VTOR, before main.", detail: "If it does not run the chip stays on the internal oscillator (16 MHz on STM32F4) and every baud rate and timer is wrong.", why: "A board running at a quarter speed after a jump is this call missing.", relatedLesson: "from-reset-vector-to-main" },
  { id: "priority-inversion", term: "priority inversion", aliases: ["unbounded priority inversion", "bounded priority inversion"], short: "A high-priority task waits on a lock held by a low-priority task; if medium-priority tasks preempt the holder, the wait becomes unbounded.", detail: "Bounded inversion (waiting for the holder's critical section) is unavoidable; unbounded inversion is the fault, fixed by priority inheritance or ceiling and short critical sections.", why: "The classic RTOS fault; reset the Mars Pathfinder lander in 1997.", relatedLesson: "priority-inversion" },
  { id: "priority-inheritance", term: "priority inheritance", aliases: ["inheritance protocol"], short: "A kernel rule that raises a lock holder to the priority of the highest task blocked on it, so medium tasks cannot preempt it; priority ceiling raises any holder to the highest user's priority for the lock's duration.", detail: "FreeRTOS mutexes inherit; binary and counting semaphores do not. Ceiling also prevents deadlock between nested locks at the cost of knowing every user at design time.", why: "What a mutex does that a semaphore does not.", relatedLesson: "priority-inversion" },
  { id: "mutex", term: "mutex", aliases: ["mutual exclusion", "xSemaphoreCreateMutex"], short: "A lock with an owner, taken and given by the same task, that provides priority inheritance in FreeRTOS. Not usable from an ISR.", detail: "Use it to protect a shared resource between tasks. For signalling from an ISR, use a semaphore, a queue or a task notification instead.", why: "Choosing a mutex over a binary semaphore is the difference between bounded and unbounded blocking.", relatedLesson: "priority-inversion" },
  { id: "semaphore", term: "semaphore", aliases: ["binary semaphore", "counting semaphore", "xSemaphoreCreateBinary"], short: "A signalling primitive: a binary semaphore is a one-slot flag, a counting semaphore a counter. Neither has an owner, so neither provides priority inheritance.", detail: "Right for 'event happened' from an ISR to a task; wrong as a lock between tasks, where its lack of inheritance creates unbounded priority inversion.", why: "The most common misuse in RTOS code.", relatedLesson: "priority-inversion" },
  { id: "queue", term: "queue", aliases: ["message queue", "xQueueSendFromISR", "xQueueReceive"], short: "An RTOS primitive that copies fixed-size items from a producer to a consumer atomically and holds a backlog; the standard ISR-to-task handoff.", detail: "Size it from production rate times worst-case consumer delay, add margin, and count drops when the send fails.", why: "Replaces the shared-buffer-and-flag race with a kernel-guaranteed copy.", relatedLesson: "isr-to-task-handoff" },
  { id: "torn-read", term: "torn read", aliases: ["torn write", "data race"], short: "A multi-word read interrupted part-way so the result mixes two different records; a data race between an ISR and a task.", detail: "volatile does not prevent it; only an atomic handoff (queue copy, masked interrupts around the copy) does.", why: "Shows as a rare, plausible-looking wrong record, once in thousands.", relatedLesson: "isr-to-task-handoff" },
  { id: "fromisr", term: "FromISR", aliases: ["xSemaphoreGiveFromISR", "portYIELD_FROM_ISR", "FromISR API"], short: "The FreeRTOS API variants that may be called from an interrupt: they never block and report whether a higher-priority task was woken so the ISR can request a context switch.", detail: "Calling a non-FromISR function from an ISR corrupts the kernel or trips configASSERT. The interrupt's priority must also be at or above configMAX_SYSCALL_INTERRUPT_PRIORITY.", why: "Three rules every ISR in a FreeRTOS system must follow.", relatedLesson: "isr-to-task-handoff" },
  { id: "stream-buffer", term: "stream buffer", aliases: ["message buffer", "double buffer", "ping-pong buffer"], short: "Handoff primitives for data streams: stream and message buffers for bytes between one writer and one reader; a double (ping-pong) buffer lets DMA fill one half while the task processes the other.", detail: "Choose by rate and shape: queue for records, stream buffer for bytes, DMA double buffer for audio or ADC rates with only a half-complete interrupt.", why: "Knowing which handoff fits which rate is a design-level skill.", relatedLesson: "isr-to-task-handoff" },
  { id: "task-notification", term: "task notification", aliases: ["direct-to-task notification", "vTaskNotifyGiveFromISR"], short: "A lightweight FreeRTOS signal to one specific task, cheaper than a semaphore, with no holder and no inheritance.", detail: "Use it when the ISR only needs to say 'something happened' and the data lives in a register or a DMA buffer.", why: "The cheapest way to wake a task from an interrupt.", relatedLesson: "isr-to-task-handoff" },
  { id: "stack-high-water", term: "stack high-water mark", aliases: ["high-water mark", "uxTaskGetStackHighWaterMark", "stack margin"], short: "The smallest amount of stack a task has ever had free, reported by the kernel; a measure of how close it has come to overflow.", detail: "Check it under worst-case load and fail a release test below a margin. It rules stack overflow in or out in one snapshot.", why: "First thing to read when an RTOS system misbehaves.", relatedLesson: "priority-inversion" },
  { id: "image-header", term: "image header", aliases: ["image trailer", "boot flag", "A/B slots", "slot"], short: "Metadata in front of a firmware image: magic, length, version, hardware ID and CRC or signature. A boot flag or trailer records which slot (A or B) is selected and confirmed.", detail: "Write the body, verify, then write the boot flag last as a single word so a power cut leaves a bootable unit; the new image must confirm itself or the bootloader falls back.", why: "The structure that makes updates survive power loss.", relatedLesson: "bootloaders-images-and-recovery" },
  { id: "device-tree", term: "device tree", aliases: ["DTB", "DTS", "device tree blob", "compatible string", "overlay"], short: "A data file describing hardware the kernel cannot discover (buses, addresses, pin muxing, clocks); compiled from .dts to .dtb and passed to the kernel by U-Boot.", detail: "status enables a node, compatible matches a driver, reg gives the address; /proc/device-tree shows the tree actually in use. A disabled or mistyped node hides a device.", why: "Where most 'my sensor is missing' faults on Linux boards live.", relatedLesson: "embedded-linux-boot-chain" },
  { id: "u-boot", term: "U-Boot", aliases: ["SPL", "first-stage loader", "bootcmd", "bootargs"], short: "The common embedded Linux bootloader: a first stage (SPL) initialises DRAM, then U-Boot loads the kernel, device tree blob and initramfs and jumps to the kernel with boot arguments such as the root filesystem.", detail: "Its environment chooses which device tree is loaded; a stale environment after a hardware change is a common cause of missing devices.", why: "Stage three of the boot chain, and the one with a shell.", relatedLesson: "embedded-linux-boot-chain" },
  { id: "kernel-user-space", term: "kernel space and user space", aliases: ["kernel space", "user space", "dmesg", "sysfs", "/dev"], short: "Kernel space holds drivers, the scheduler, filesystems and the parsed device tree, running privileged; user space holds applications and tools, reaching hardware only through /dev nodes and /sys attributes.", detail: "dmesg shows the kernel's log, /sys exposes device attributes, /dev/i2c-N lets user space poke a bus even without a bound driver.", why: "The boundary that explains why i2cget works while a driver does not.", relatedLesson: "embedded-linux-boot-chain" },
  { id: "i2cdetect", term: "i2cdetect", aliases: ["i2c-tools", "i2cget"], short: "A user-space tool that probes every address on an I2C bus and prints which ones acknowledge.", detail: "It reports only buses the kernel registered; 'bus does not exist' is a device-tree or driver matter, not a wiring one.", why: "The last of the four checks for a missing I2C device, not the first.", relatedLesson: "embedded-linux-boot-chain" },
  // --- Test automation, HIL, reliability ---
  { id: "scpi", term: "SCPI", aliases: ["Standard Commands for Programmable Instruments", "*IDN?", "*RST", "*OPC?"], short: "The text command language of bench instruments: common commands starting with * and subsystem trees such as CONF:VOLT:DC; a trailing ? makes a query.", detail: "Wrong commands go into the instrument's error queue instead of raising errors; read SYST:ERR? to find them. *OPC? returns 1 when pending operations have completed and is the proper synchronisation point.", why: "The language every automated measurement script speaks.", relatedLesson: "talking-to-an-instrument-with-pyvisa" },
  { id: "visa", term: "VISA", aliases: ["PyVISA", "VISA resource", "resource string"], short: "The driver layer that makes USB, LAN, GPIB and serial instruments look alike; PyVISA is its Python binding, with ResourceManager, open_resource, write, query and read.", detail: "The resource string (USB0::0x2A8D::0x1301::MY57200123::INSTR) is the address and contains the serial number that belongs in your log.", why: "Four calls cover most instrument automation.", relatedLesson: "talking-to-an-instrument-with-pyvisa" },
  { id: "nplc", term: "NPLC", aliases: ["power-line cycles", "integration time"], short: "Number of power-line cycles a DMM integrates over per reading; 1 NPLC is 20 ms at 50 Hz. More cycles reject mains hum and lower noise at the cost of time.", detail: "Timeouts come from this arithmetic: NPLC × cycle time × readings, doubled with auto-zero. A 100-PLC reading takes about 2 s and will time out a 1 s read.", why: "Where measurement time, noise and timeouts meet.", relatedLesson: "talking-to-an-instrument-with-pyvisa" },
  { id: "error-queue", term: "error queue", aliases: ["SYST:ERR?", "Undefined header", "-113"], short: "An instrument's FIFO of rejected or faulty commands, read one entry at a time with SYST:ERR?; it answers 0,'No error' when empty and -113,'Undefined header' for an unknown command.", detail: "A script that never reads it has no idea whether its configuration was accepted. Check it after setup and on any unexpected reading.", why: "The silent failure mode of instrument automation.", relatedLesson: "talking-to-an-instrument-with-pyvisa" },
  { id: "pyserial", term: "pyserial", aliases: ["serial.Serial", "readline", "reset_input_buffer", "in_waiting"], short: "The Python library for serial ports: Serial(port, baud, timeout), write(bytes), readline() → bytes, reset_input_buffer() to discard stale input, in_waiting for bytes pending.", detail: "readline returns whatever arrived when the timeout expires, possibly a partial line, and does not raise; bytes arriving later stay in the buffer for the next read.", why: "The library behind most device-under-test automation.", relatedLesson: "serial-automation-and-test-logs" },
  { id: "stale-reply", term: "stale reply", aliases: ["late reply", "one command late", "reply misattribution"], short: "A reply that arrives after the host stopped waiting for it, stays in the input buffer, and is consumed as the answer to the next command, shifting every later reply by one.", detail: "Prevented by flushing before each command, reading to a per-command deadline, accepting only complete lines, and matching each reply to its request by tag or shape.", why: "The usual mechanism behind a flaky serial test.", relatedLesson: "serial-automation-and-test-logs" },
  { id: "request-reply", term: "request-reply protocol", aliases: ["sequence tag", "reply matching", "command tag"], short: "An exchange where each request carries a tag or has a known reply shape, so the host can tell which reply belongs to which request and discard late or unexpected ones.", detail: "Flush, send tagged and terminated, read to a deadline, match, fail loudly. Log every byte in and out with timestamps.", why: "What turns a serial script into a test whose log can be trusted.", relatedLesson: "serial-automation-and-test-logs" },
  { id: "flaky-test", term: "flaky test", aliases: ["intermittent test failure", "flakiness"], short: "A test that passes and fails without a change in the thing under test; usually timing, stale state or unmatched replies in the harness rather than a defect in the device.", detail: "Measure the failure rate, read the log with timestamps, find the mechanism. A sleep or a retry hides it; a protocol fix removes it.", why: "Where test automation loses or earns a team's trust.", relatedLesson: "serial-automation-and-test-logs" },
  { id: "hil", term: "hardware in the loop", aliases: ["HIL", "HIL rig", "hardware-in-the-loop"], short: "Testing the real controller with its real I/O electrically connected to a rig that runs the plant model in real time and drives real voltages, currents and bus frames.", detail: "Proves I/O wiring and mapping, timing under real interrupts and bus traffic, and fault handling via fault insertion. Proves nothing the plant model leaves out.", why: "The level where mis-wired channels and unhandled open sensors are caught.", relatedLesson: "sil-hil-what-each-proves" },
  { id: "sil", term: "software in the loop", aliases: ["SIL", "MIL", "PIL", "model in the loop", "processor in the loop", "software-in-the-loop"], short: "Test levels defined by what is real: MIL the control model, SIL the code compiled for a PC, PIL the code on the target processor, HIL the whole controller with real I/O.", detail: "Send each bug class to the lowest level that can catch it: tuning at MIL, logic at SIL, timing and fixed-point at PIL, I/O and electrical faults at HIL.", why: "The ladder behind 'we tested the right thing at the right level'.", relatedLesson: "sil-hil-what-each-proves" },
  { id: "fault-insertion", term: "fault-insertion unit", aliases: ["FIU", "fault insertion", "breakout box"], short: "The part of a HIL rig that can open, short to ground or battery, or cross any controller wire on command, so fault-handling requirements can be verified end to end.", detail: "It is the negative half of verification at system level: the proof that an open sensor is detected in time, not just that a good sensor is read.", why: "Why HIL can verify safety mechanisms that a bench cannot.", relatedLesson: "sil-hil-what-each-proves" },
  { id: "plant-model", term: "plant model", aliases: ["plant", "real-time model", "model fidelity"], short: "The simulation of the thing the controller controls (motor, aircraft, patient, process) that a HIL rig runs in real time; its fidelity bounds what HIL can prove.", detail: "Validate it against measured plant data and state the validation evidence in the test report; keep a final real-plant test layer for what it omits.", why: "A HIL pass is only as good as the plant model.", relatedLesson: "sil-hil-what-each-proves" },
  { id: "fmea", term: "FMEA", aliases: ["failure mode and effects analysis", "design FMEA", "process FMEA", "FMECA"], short: "A table that asks, for every item and function, how it can fail, what the effect is, what causes it, what controls exist, and scores severity, occurrence and detection to prioritise action.", detail: "Design FMEA covers the product; process FMEA covers how it is built. Firmware appears as cause, control and item. Every action traces to a design change and a test.", why: "The common reliability language across automotive, aerospace, medical and industrial.", relatedLesson: "fmea-for-a-small-embedded-product" },
  { id: "severity-occurrence-detection", term: "severity, occurrence and detection", aliases: ["severity", "occurrence", "detection score", "S O D"], short: "The three 1-to-10 FMEA scores: severity of the effect (10 worst), occurrence of the cause (10 most frequent), detection of the mode before the user (10 means no detection; high is bad).", detail: "Prevention lowers occurrence; detection controls lower detection; only a design change to the effect lowers severity. A range check never changes S.", why: "The scores reviewers check you understand, especially the direction of D.", relatedLesson: "fmea-for-a-small-embedded-product" },
  { id: "rpn", term: "RPN", aliases: ["risk priority number", "action priority", "AP table"], short: "Risk priority number = severity × occurrence × detection, 1 to 1000, used to rank FMEA rows; replaced in the 2019 AIAG-VDA handbook by action-priority tables that look at severity first.", detail: "RPN can rank a 9×2×2 safety item below a 4×5×5 nuisance; rows with severity 9 or 10 get an action regardless of the product.", why: "Know the number, and know why reviewers no longer trust it alone.", relatedLesson: "fmea-for-a-small-embedded-product" },
  { id: "single-point-of-failure", term: "single point of failure", aliases: ["SPOF", "single-point failure", "redundancy"], short: "A failure mode whose single occurrence produces the top-level effect with no independent prevention or detection between them.", detail: "FMEA rows with high severity and no detection are the SPOFs; they get redundancy or diverse detection first (a thermal fuse beside the control relay).", why: "The first thing a safety reviewer looks for.", relatedLesson: "fmea-for-a-small-embedded-product" },
  { id: "plausibility-check", term: "plausibility check", aliases: ["range check", "sanity check", "rate-of-change check"], short: "A firmware check that a reading is physically possible: within the sensor's valid range, and not changing faster than the process can; failing it declares a sensor fault.", detail: "Cheap detection controls that turn an open or shorted sensor into a handled fault instead of a wrong value acted upon.", why: "The most common firmware mitigation in an FMEA.", relatedLesson: "fmea-for-a-small-embedded-product" },
  // --- Standards, transfer, interviews ---
  { id: "do-178c", term: "DO-178C", aliases: ["DO-178", "DO-330", "DO-254", "DO-160"], short: "The civil-avionics software process standard: objectives (evidence that must exist) scaled by DAL A to E; DO-254 is its counterpart for complex hardware, DO-160 the environmental test standard, DO-330 tool qualification.", detail: "Verification under it is requirements-based with traceability and structural coverage (statement at C, decision at B, MC/DC at A). Nobody is 'DO-178C certified'; aircraft are certified, software is found compliant, people work to the process.", why: "The standard most avionics job adverts name, and the one most often misdescribed.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "dal", term: "DAL", aliases: ["Development Assurance Level", "DAL A", "DAL C", "software level"], short: "Development Assurance Level, A (catastrophic failure condition) to E (no effect), assigned by the ARP4761 safety assessment and used by DO-178C and DO-254 to scale their objectives.", detail: "Not convertible to ASIL or SIL. Changes with the level: number of objectives, independence, and the structural coverage criterion.", why: "Where every 'what level was it?' question starts.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "mcdc", term: "MC/DC", aliases: ["modified condition/decision coverage", "decision coverage", "statement coverage", "structural coverage"], short: "Modified condition/decision coverage: every condition in a decision shown to independently affect its outcome; the structural coverage criterion DO-178C requires at DAL A, above decision coverage (DAL B) and statement coverage (DAL C).", detail: "Structural coverage measures how much of the code the requirements-based tests exercised; uncovered code must be justified (dead, deactivated) or the requirements and tests improved.", why: "The verification ladder interviewers ask about by level.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "arp4761", term: "ARP4761", aliases: ["ARP4754A", "FHA", "functional hazard assessment", "system safety assessment"], short: "The aerospace safety-assessment method (functional hazard assessment, preliminary and system safety assessments, fault trees, FMEA) that classifies failure conditions and so assigns DAL; ARP4754A is the system-development process beside it.", detail: "The source of the number that drives everything in DO-178C and DO-254.", why: "Knowing where DAL comes from separates understanding from vocabulary.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "iso-26262", term: "ISO 26262", aliases: ["26262", "functional safety (automotive)", "HARA", "hazard analysis and risk assessment", "safety goal"], short: "Automotive functional safety for road-vehicle E/E systems: a hazard analysis and risk assessment (HARA) scores severity, exposure and controllability to assign an ASIL, each hazard gets a safety goal, and requirements, verification rigour and hardware metrics follow down the V-model.", detail: "Safety mechanisms are shown to work with fault injection, typically on a HIL rig, within the fault-tolerant time interval.", why: "The automotive standard every embedded advert lists.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "asil", term: "ASIL", aliases: ["automotive safety integrity level", "ASIL D", "ASIL B", "QM"], short: "Automotive Safety Integrity Level, QM (no safety requirement) then A to D, read from the ISO 26262 table of severity, exposure and controllability for each hazardous event.", detail: "Not convertible to DAL or SIL. Raises verification method requirements, independence and hardware architectural metrics.", why: "The automotive counterpart of DAL, assigned by a different method.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "aspice", term: "ASPICE", aliases: ["Automotive SPICE", "process capability"], short: "Automotive SPICE, a process-capability assessment model (levels 0 to 5) for requirements, design, test and configuration management; demanded by OEMs and independent of safety.", detail: "Evidence under it is the process itself: plans, traceability, review records, metrics. It is not a safety standard and assigns no level to a function.", why: "Often confused with ISO 26262; knowing the difference is a cheap signal.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "autosar", term: "AUTOSAR", aliases: ["AUTOSAR Classic", "AUTOSAR Adaptive", "RTE"], short: "A standardised automotive software architecture and set of interfaces (basic software, runtime environment, application components; an Adaptive platform for high-performance computers). An architecture, not a safety or process standard.", detail: "Provides building blocks that safety architectures use; it does not assign ASIL or define a process.", why: "The third automotive acronym, and the one that is about structure rather than rigour.", relatedLesson: "avionics-and-automotive-standards-scope" },
  { id: "iec-62304", term: "IEC 62304", aliases: ["62304", "software safety class", "Class C", "Class B", "Class A"], short: "The medical-device software life-cycle standard; software is assigned a safety class A (no injury possible), B (non-serious injury) or C (death or serious injury) from the risk analysis, and the required activities and records grow with the class.", detail: "Classification follows harm, not code complexity; verification records live in the design history file traced to requirements and risk controls.", why: "The medical counterpart of DO-178C, with classes instead of levels.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "iec-60601", term: "IEC 60601-1", aliases: ["60601", "IEC 60601-1-2", "basic safety", "essential performance", "means of protection"], short: "The electrical-safety standard for medical electrical equipment: basic safety (leakage currents, insulation, creepage and clearance, means of patient and operator protection) and essential performance (functions whose loss creates unacceptable risk); -1-2 is the EMC collateral.", detail: "Hardware and test engineers run leakage, dielectric and EMC tests to it, with essential performance maintained during immunity tests.", why: "Where medical electrical tests and their limits come from.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "iso-13485", term: "ISO 13485", aliases: ["13485", "design history file", "DHF"], short: "The medical-device quality management system standard; the design history file (DHF) it requires holds the evidence that the device was designed and verified as planned; CAPA is its corrective and preventive action process.", detail: "Every verification protocol and report lands in the DHF, traced to requirements and risk controls.", why: "The system the records live in.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "iso-14971", term: "ISO 14971", aliases: ["14971", "risk management file", "risk file", "risk control"], short: "Medical-device risk management: identify hazards, estimate and evaluate risk, control it, and maintain a risk management file through the product's life; the source of the limits in safety requirements.", detail: "The medical cousin of hazard analysis and FMEA; a risk control is what a verification test proves works.", why: "Where a medical interviewer expects 'risk control' instead of 'safety requirement'.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "iec-61508", term: "IEC 61508", aliases: ["61508", "IEC 61511", "safety instrumented system", "FMEDA", "proof test"], short: "The generic functional-safety standard for electrical, electronic and programmable electronic safety-related systems; assigns SIL 1 to 4 to a safety function from the risk reduction it must provide, with targets for random hardware failure (from FMEDA), hardware fault tolerance and systematic capability. IEC 61511 applies it to process-industry safety instrumented systems.", detail: "Test engineers produce FMEDA inputs, proof-test procedures and fault-injection evidence for diagnostic coverage.", why: "The industrial safety standard, and the origin of the SIL ladder.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "safety-integrity-level", term: "safety integrity level", aliases: ["SIL 1", "SIL 2", "SIL 3", "SIL 4", "PFD", "PFH"], short: "The IEC 61508 level, 1 to 4, of a safety function, each an order of magnitude in the probability of dangerous failure on demand (PFD, low demand) or per hour (PFH, continuous).", detail: "The same acronym SIL also means software-in-the-loop in test environments; context tells which. Not convertible to ASIL or DAL.", why: "The acronym clash interviewers notice, and the ladder that is not an exchange rate.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "diagnostic-coverage", term: "diagnostic coverage", aliases: ["DC", "hardware fault tolerance", "systematic capability"], short: "The fraction of dangerous failures that a built-in test or monitor detects before they matter; credited in the FMEDA only when a fault-injection test has shown the monitor works. Hardware fault tolerance and systematic capability are the other two legs of a SIL claim.", detail: "Watchdogs, plausibility checks, output readback and configuration CRCs each raise it; your fault-injection tests are the evidence behind the number.", why: "What turns a test engineer's fault-injection work into a safety number.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "performance-level", term: "performance level", aliases: ["PL a", "PL e", "ISO 13849", "IEC 62061", "machinery safety"], short: "The ISO 13849 ladder, a to e, for machinery safety functions, with categories describing the architecture; IEC 62061 is the IEC 61508-derived alternative for machinery.", detail: "Another non-convertible ladder; the evidence is category and PL calculations plus validation records.", why: "Appears in industrial automation adverts beside SIL.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "iec-62443", term: "IEC 62443", aliases: ["62443", "industrial cybersecurity", "security level"], short: "Industrial automation and control system cybersecurity: security levels for zones and conduits, product and process requirements; increasingly demanded alongside functional safety.", detail: "Not a safety standard; its evidence is threat analysis and security test records.", why: "The security standard that now sits beside IEC 61508 in industrial roles.", relatedLesson: "medical-and-industrial-standards-scope" },
  { id: "transfer-sentence", term: "transfer sentence", aliases: ["skills transfer", "transferable skill", "cross-industry"], short: "The pattern for describing a skill to another industry: what I did (verb and object), the evidence (number, instrument, artefact), their name for it.", detail: "Does the translation for the reader and offers something verifiable; pair it with an honest boundary of what you have practised but not done professionally.", why: "The sentence that makes an avionics background read as relevant in automotive, medical, industrial or consumer roles.", relatedLesson: "same-skills-different-industries" },
  { id: "training-vs-employment", term: "training is not employment", aliases: ["simulated practice", "portfolio work", "professional experience"], short: "The academy's rule: lessons, simulated missions and portfolio projects are learning and are described as learning; they are never presented as employment history or as 'experience' without the boundary stated.", detail: "'I have practised HIL concepts in simulation' is strong; 'I have HIL experience' without a rig collapses on the first follow-up.", why: "The honesty rule behind every interview answer here.", relatedLesson: "same-skills-different-industries" },
  { id: "portfolio-outline", term: "portfolio outline", aliases: ["one-page outline", "project outline", "simulated versus hardware"], short: "A one-page project description in six headings: problem and scope, constraints and decisions, what was built, simulated versus hardware (as a table), evidence, what is next.", detail: "Evidence means counts, measurements with instrument and trials, and artefacts someone can open; the simulated-versus-hardware table is where trust is won or lost.", why: "The document that turns a self-built project into interview evidence.", relatedLesson: "presenting-a-portfolio-project-honestly" },
  { id: "debugging-story", term: "debugging story", aliases: ["evidence, decision, outcome", "five beats", "hard bug question"], short: "An interview answer structured as symptom (with a number), evidence (instruments and rule-outs), decision (with a reason), outcome (fix and confirmation both ways, with a number) and prevention.", detail: "Prepare a 90-second version with three numbers and a five-minute version with the discarded hypotheses; cut duration, emotion and blame; never cut the instrument, the number, the confirmation or the boundary.", why: "The one answer every hardware interview contains.", relatedLesson: "telling-a-debugging-story" },
  { id: "mock-interview", term: "mock interview", aliases: ["timed mock", "mock mode"], short: "A rehearsal under interview conditions: a fixed set of questions, four minutes each, no notes, rubric revealed only after the time is up; the Interview page has a timer for it.", detail: "Grade honestly with the rubric afterwards and write one line per question on what to fix; the rating is useful only if it is true.", why: "Day 29's exercise, and the habit to keep after the 30 days.", relatedLesson: "telling-a-debugging-story" },
  // --- Fundamentals, schematics, CAN, NVIC, C/C++, drivers, analysers ---
  { id: "power-tree", term: "power tree", aliases: ["rail", "rails", "headroom"], short: "The diagram of every supply rail on a board from the input down: each regulator's type, the headroom it needs, its dissipation and the current budget of its loads, with any sequencing arrows.", detail: "Read it top down and write the minimum input, the dissipation and the burst current beside each regulator; most mystery resets are a line in this diagram.", why: "The first document to draw when a board misbehaves on power.", relatedLesson: "reading-a-power-tree" },
  { id: "dropout", term: "dropout voltage", aliases: ["dropout", "out of regulation"], short: "The minimum difference an LDO needs between input and output to regulate; below it the output follows the input.", detail: "Check headroom against the lowest input the product will see at the highest load current.", why: "A battery that sags under load takes the rail with it when headroom is gone.", relatedLesson: "reading-a-power-tree" },
  { id: "ir-drop", term: "I × R drop", aliases: ["IR drop", "voltage sag", "rail sag", "trace resistance"], short: "The voltage lost across the resistance of traces and connectors when current flows: a 0.4 Ω path at 0.8 A drops 0.32 V.", detail: "A rail that measures fine at the regulator can sag at a remote load during a burst; measure at the load, under load, with a scope.", why: "The arithmetic behind most far-end resets.", relatedLesson: "reading-a-power-tree" },
  { id: "bulk-capacitor", term: "bulk capacitance", aliases: ["bulk capacitor", "bulk cap"], short: "Microfarads of capacitance at a regulator output and at remote loads that supply millisecond-scale current bursts while the regulator and the trace catch up, and set the regulator's load-transient response.", detail: "Distinct from decoupling (100 nF per pin for nanosecond edges); the regulator datasheet states the capacitance and ESR range it is stable with.", why: "The fix for a rail that sags under a burst.", relatedLesson: "reading-a-power-tree" },
  { id: "psrr", term: "PSRR", aliases: ["power-supply rejection ratio", "supply ripple rejection"], short: "Power-supply rejection ratio: how much input ripple a regulator or amplifier attenuates, high at low frequencies and falling with frequency.", detail: "A buck's switching ripple at hundreds of kilohertz passes an LDO almost unattenuated; sensitive analogue rails need a filter in front.", why: "Why an analogue rail inherits the noise of the rail above it.", relatedLesson: "reading-a-power-tree" },
  { id: "saturation", term: "saturation (op-amp)", aliases: ["output at a rail", "rail-stuck", "output swing"], short: "An op-amp output that cannot go further toward a supply rail: the circuit asked for more than the rail allows, the feedback is open, or the inputs are outside the common-mode range.", detail: "The datasheet's output voltage swing and input common-mode range lines say what the part can do on your supply.", why: "The most common single-supply op-amp fault.", relatedLesson: "op-amp-sanity-checks" },
  { id: "virtual-short", term: "virtual short", aliases: ["virtual ground", "inputs equal"], short: "With negative feedback and an unsaturated output, an op-amp drives its two inputs to within millivolts of each other.", detail: "Measuring the two inputs separates 'the amplifier is working but asked the impossible' from 'the loop is not in control'.", why: "One measurement that settles most op-amp arguments.", relatedLesson: "op-amp-sanity-checks" },
  { id: "input-offset", term: "input offset voltage", aliases: ["offset voltage", "input bias current", "bias current"], short: "The small voltage an op-amp needs between its inputs to zero its output, multiplied by the noise gain; input bias current flowing through the source resistance adds a similar error.", detail: "Millivolt errors at the output that do not change with signal are offset and bias; choose a precision part or calibrate.", why: "Explains a stage that is accurate except for a constant few millivolts.", relatedLesson: "op-amp-sanity-checks" },
  { id: "gbw", term: "gain-bandwidth product", aliases: ["GBW", "slew rate", "unity-gain stable"], short: "The frequency at which an op-amp's open-loop gain falls to one; closed-loop bandwidth is roughly GBW divided by the gain. Slew rate limits how fast the output can move. A part that is not unity-gain stable needs a minimum closed-loop gain.", detail: "A 1 MHz GBW part at gain 100 has 10 kHz of bandwidth; a 0.5 V/µs part turns a fast sine into a triangle.", why: "The two datasheet numbers behind 'it reads low at speed'.", relatedLesson: "op-amp-sanity-checks" },
  { id: "lsb", term: "LSB", aliases: ["least significant bit (ADC)", "1 LSB", "resolution (ADC)", "ENOB"], short: "For an N-bit ADC with reference V_ref, one LSB is V_ref ÷ 2^N: the voltage step between adjacent codes. ENOB, the effective number of bits, is the resolution actually achieved after noise.", detail: "12 bits on 3.3 V is 0.806 mV; on 2.5 V, 0.610 mV. Quantisation noise is LSB ÷ √12 rms.", why: "Resolution is a count; accuracy is the reference and the errors on top.", relatedLesson: "adc-resolution-reference-and-noise" },
  { id: "adc-reference", term: "ADC reference", aliases: ["V_ref", "VREF+", "voltage reference"], short: "The voltage the ADC divides into codes; its accuracy, drift, noise and ripple appear in every conversion.", detail: "A supply rail used as the reference carries the board's switching ripple, correlated sample to sample, which averaging cannot remove; a dedicated reference IC with local decoupling is the fix.", why: "The usual culprit behind jitter that averaging does not cure.", relatedLesson: "adc-resolution-reference-and-noise" },
  { id: "sample-time", term: "sample time (SAR ADC)", aliases: ["sampling time", "source impedance", "acquisition time"], short: "The time a successive-approximation ADC connects its sampling capacitor to the input; it must be long enough for the capacitor to charge through the source impedance to within half an LSB.", detail: "Too short on a high-impedance source reads low and copies the previous channel's value; the reference manual's table gives cycles against impedance.", why: "The reason a second ADC channel reads the first channel's voltage.", relatedLesson: "adc-resolution-reference-and-noise" },
  { id: "oversampling", term: "oversampling", aliases: ["averaging", "decimation", "dither"], short: "Taking n samples and averaging reduces uncorrelated noise by √n; oversampling with decimation adds k bits for 4^k samples provided the noise dithers the codes by at least about 1 LSB.", detail: "Neither removes systematic errors (reference accuracy, sample time) or correlated noise (reference ripple aliased into a wander).", why: "What averaging can and cannot buy.", relatedLesson: "adc-resolution-reference-and-noise" },
  { id: "schematic-review", term: "schematic review", aliases: ["design review (hardware)", "review finding", "must fix"], short: "A structured walk of a schematic before fabrication, in bring-up order (power, reset, clock, boot straps, debug), then every interface boundary, then what is missing, with findings recorded as ID, severity, net, evidence, consequence and proposal.", detail: "An hour of review replaces a three-week board spin; findings cite datasheets and the vendor reference design.", why: "Where test engineers earn a seat by knowing how boards fail.", relatedLesson: "reading-a-schematic-like-a-reviewer" },
  { id: "boot-strap", term: "boot strap", aliases: ["configuration strap", "floating pin"], short: "A pin read at reset to select boot mode or configuration; it must be tied through a resistor to a defined level with an override, never left floating.", detail: "A floating BOOT0 selects the ROM bootloader on noise or humidity: the humid-morning fault.", why: "One of the three faults that most often cost a spin.", relatedLesson: "reading-a-schematic-like-a-reviewer" },
  { id: "level-compatibility", term: "level compatibility", aliases: ["5 V tolerant", "FT pin", "VIH", "VOH", "logic levels"], short: "Two parts can talk when the driver's VOH exceeds the receiver's VIH and its VOL is below VIL at the currents involved, and when no pin sees a voltage above what it tolerates; FT pins on STM32 tolerate 5 V.", detail: "An open-drain bus between a 5 V device and FT pins works with pull-ups to 5 V and open-drain MCU outputs; a non-FT pin needs a level shifter.", why: "Settled by the pin table, not by assumption.", relatedLesson: "reading-a-schematic-like-a-reviewer" },
  { id: "absolute-maximum", term: "absolute maximum ratings", aliases: ["recommended operating conditions", "typical vs maximum", "min/typ/max"], short: "Datasheet limits beyond which a part may be damaged; never operating points. Recommended operating conditions are the ranges within which the electrical characteristics (min, typical, max, with conditions) are guaranteed.", detail: "Budgets use min and max under the product's real conditions; typical is a sample at 25 °C and is for estimates only.", why: "The three sections and three columns that most datasheet errors confuse.", relatedLesson: "datasheet-triage" },
  { id: "theta-ja", term: "θJA", aliases: ["thermal resistance", "junction temperature", "T_J max"], short: "Junction-to-ambient thermal resistance for a package on the datasheet's test board; junction temperature is ambient plus dissipation × θJA and must stay below the maximum with margin.", detail: "The test board is usually larger than yours, so derate and measure.", why: "How a dissipation number becomes a temperature.", relatedLesson: "datasheet-triage" },
  { id: "nvic", term: "NVIC", aliases: ["nested vectored interrupt controller", "interrupt priority", "preemption priority", "sub-priority", "priority grouping"], short: "The Cortex-M interrupt controller: a smaller priority number is more urgent; the priority grouping splits the bits into preemption priority (which can interrupt a running handler) and sub-priority (which only orders pending handlers).", detail: "STM32 implements 4 bits (16 levels); HAL's grouping 4 makes them all preemption bits. Pending, active and tail-chaining describe the states and the entry optimisation.", why: "Where 'I set it higher and it did not preempt' comes from.", relatedLesson: "interrupts-and-nvic-priorities" },
  { id: "syscall-priority", term: "configMAX_SYSCALL_INTERRUPT_PRIORITY", aliases: ["syscall interrupt priority", "BASEPRI", "PRIMASK", "interrupt latency"], short: "The FreeRTOS limit: only interrupts with a priority number at or above it (less urgent) may call FromISR API; more urgent interrupts run during kernel critical sections (implemented with BASEPRI) and must not touch the kernel. PRIMASK masks all configurable interrupts.", detail: "Interrupt latency is bounded by stacking time plus the longest masked section plus the longest handler of equal or higher urgency; measure it with a GPIO on a scope.", why: "The rule behind every FreeRTOS priority table.", relatedLesson: "interrupts-and-nvic-priorities" },
  { id: "dominant-recessive", term: "dominant and recessive", aliases: ["dominant bit", "recessive bit", "wired-AND", "arbitration (CAN)"], short: "CAN's two bus states: dominant (logical 0, the pair driven apart) overrides recessive (logical 1, the pair floating together), a wired-AND that lets nodes arbitrate bit by bit; the lowest identifier wins without corrupting the winning frame.", detail: "Standard frames carry 11-bit identifiers, extended 29-bit; a node that sends recessive and reads dominant has lost and becomes a receiver.", why: "Why identifiers are priorities.", relatedLesson: "can-arbitration-error-frames-and-bus-off" },
  { id: "bus-off", term: "bus-off", aliases: ["error passive", "error active", "TEC", "REC", "error counter", "error frame"], short: "CAN fault confinement: a transmit error adds 8 to the transmit error counter (TEC), a receive error 1 to REC, a success subtracts 1; error active below 128, error passive at or above 128, bus-off when TEC exceeds 255, after which the node leaves the bus until it sees 128 × 11 recessive bits and, usually, software permits recovery.", detail: "Error frames (six dominant bits) destroy a corrupted frame so it is retransmitted. A silent node with TEC 256 and REC 0 failed its own transmissions.", why: "Why a node falls silent and how it comes back.", relatedLesson: "can-arbitration-error-frames-and-bus-off" },
  { id: "can-termination", term: "CAN termination", aliases: ["120 Ω", "60 Ω", "sample point", "bit stuffing"], short: "High-speed CAN needs 120 Ω at each end of the bus, which reads about 60 Ω between CAN_H and CAN_L with power off; 120 Ω means one terminator is missing. The sample point (typically 75 to 87.5 % of the bit) and bit rate must match on every node; bit stuffing inserts an opposite bit after five identical ones.", detail: "The first measurement on any CAN bus that misbehaves.", why: "Three numbers that diagnose most CAN faults.", relatedLesson: "can-arbitration-error-frames-and-bus-off" },
  { id: "struct-overlay", term: "struct overlay", aliases: ["register map struct", "peripheral struct", "GPIO_TypeDef", "base address"], short: "A C typedef whose members match a peripheral's register offsets, cast from the peripheral's base address so that GPIOA->ODR is an access to base + offset; every member volatile, reserved members for gaps, widths per the map, never packed.", detail: "The vendor CMSIS headers provide these per peripheral; pass the pointer into drivers so the same code runs against a RAM-backed fake on the host.", why: "What every register access compiles down to.", relatedLesson: "pointers-to-hardware" },
  { id: "access-type", term: "register access type", aliases: ["read-only register", "write-only register"], short: "The map's marking of how a register or bit may be accessed: rw, r (read-only), w (write-only), rc_w0/rc_w1 (read, clear by writing 0 or 1), rs (read, set). Read-modify-write on write-only or clear-on-write registers corrupts state silently; atomic set/reset registers such as BSRR exist to avoid it.", detail: "Check the column before every read-modify-write.", why: "The silent fault class the compiler cannot see.", relatedLesson: "pointers-to-hardware" },
  { id: "raii", term: "RAII", aliases: ["resource acquisition is initialisation", "guard object", "scope guard", "LockGuard"], short: "The C++ idiom of acquiring a resource in a constructor and releasing it in the destructor, which runs on every exit path; used for critical sections (save and restore PRIMASK), chip-select lines, mutexes and peripheral power.", detail: "Delete copying so a guard cannot be released twice; the compiled code matches hand-written paired calls without the possibility of forgetting one.", why: "The one C++ feature that justifies the language on a microcontroller.", relatedLesson: "raii-for-peripherals" },
  { id: "embedded-cpp-subset", term: "embedded C++ subset", aliases: ["-fno-exceptions", "-fno-rtti", "constexpr", "enum class"], short: "The C++ features firmware teams typically use (constexpr, enum class, templates for register access, std::array, references, RAII, static polymorphism) and switch off (exceptions, RTTI, heap after start-up, thread-safe statics), with global constructors kept trivial because they run before main in unspecified order.", detail: "The flags are compiler settings and the reasons are flash, timing and determinism.", why: "The standard answer to 'what C++ do you use on an MCU?'.", relatedLesson: "raii-for-peripherals" },
  { id: "driver-model", term: "driver model", aliases: ["polling", "interrupt-driven", "DMA", "direct memory access"], short: "The three ways to move data between a peripheral and memory: polling (the CPU waits), interrupts (a handler per event), DMA (a controller moves blocks with interrupts at half and full buffer); chosen by event rate, latency tolerance and CPU budget.", detail: "An interrupt per byte at a megabit costs a large CPU fraction; DMA with half/full interrupts costs two per block.", why: "The decision behind every driver, and the usual interview question.", relatedLesson: "polling-interrupts-and-dma" },
  { id: "pwm-timer", term: "PWM timer arithmetic", aliases: ["PWM", "PSC", "ARR", "CCR", "duty cycle"], short: "On a general-purpose timer, f_PWM = f_TIM ÷ ((PSC + 1) × (ARR + 1)) and duty = CCR ÷ (ARR + 1); ARR + 1 is the number of duty steps.", detail: "A non-integer prescaler means frequency, resolution or clock must change; state the compromise.", why: "Three registers, two formulas, and one compromise to state.", relatedLesson: "polling-interrupts-and-dma" },
  { id: "cache-coherence", term: "cache coherence (DMA)", aliases: ["data cache", "cache invalidate", "non-cacheable region", "buffer ownership"], short: "On a core with a data cache (Cortex-M7), the CPU can read stale cached data after DMA wrote RAM, or DMA can read RAM before a cached write reached it; fix by invalidating or cleaning the cache per transfer, or placing DMA buffers in a non-cacheable MPU region. Buffer ownership means reading only the half DMA is not writing.", detail: "'Works on the F4, garbage on the F7' is this, every time.", why: "The two DMA traps that bite on the first board with a cache.", relatedLesson: "polling-interrupts-and-dma" },
  { id: "sample-rate-detail", term: "sample rate (logic analyser)", aliases: ["logic threshold", "protocol decoder", "trigger (analyser)", "capture"], short: "A logic analyser must sample at least four times the fastest edge rate to decode and ten times to measure timing, with the threshold set for the logic family, the ground connected, a trigger around the event and memory depth for the window; the decoder's settings (baud, CPOL/CPHA, address width, bit rate) must match the bus.", detail: "An analyser at 1 MS/s on a 400 kHz bus decodes nonsense with confidence.", why: "The setup that makes a capture trustworthy.", relatedLesson: "logic-analysers-decoding-a-bus" },
  { id: "bus-identification", term: "bus identification", aliases: ["unknown protocol", "idle level"], short: "Identifying a serial bus from a capture: count lines and idle levels, look for a clock, measure the shortest pulse for the rate, find the framing (START, chip select, start bit), confirm on a known transaction.", detail: "Open-drain rising edges and a START when data falls with the clock high is I2C; a square clock with a framing line is SPI; one line with falling start edges and no clock is UART.", why: "How to decode a bus you did not design.", relatedLesson: "logic-analysers-decoding-a-bus" },
  // --- Fundamentals: laws, passives, actives, levels, protection, instruments ---
  { id: "voltage-divider", term: "voltage divider", aliases: ["divider", "potential divider", "resistive divider"], short: "Two resistors in series across a voltage; the junction between them gives a fixed fraction of that voltage.", detail: "V_out = V_in × R2 / (R1 + R2) with R2 to ground. Seen from outside it is that voltage behind R1 in parallel with R2, so any load or meter pulls it down by a predictable amount.", why: "Sense inputs, battery monitors, level shifting and pull-up arithmetic are all dividers; loading a divider wrongly is the classic ADC mistake.", relatedLesson: "circuit-laws-on-the-bench" },
  { id: "thevenin-equivalent", term: "Thévenin equivalent", aliases: ["Thevenin equivalent", "Thévenin resistance", "Thevenin resistance", "source resistance"], short: "Any network of sources and resistors, seen from two terminals, behaves like one voltage source in series with one resistor.", detail: "For a divider the Thévenin voltage is the unloaded output and the Thévenin resistance is R1 in parallel with R2. A load then forms a second divider against that resistance, which is how loading error and rail sag are computed.", why: "Saying 'the node is 1.65 V behind 50 kΩ' is how engineers reason about loading in one breath; interviewers listen for it.", relatedLesson: "circuit-laws-on-the-bench" },
  { id: "kirchhoff-laws", term: "Kirchhoff's laws", aliases: ["KVL", "KCL", "Kirchhoff's voltage law", "Kirchhoff's current law"], short: "Two bookkeeping rules: currents into a junction equal currents out, and voltages around any closed loop add to zero.", detail: "KCL makes a rail's current budget a sum of its loads; KVL makes a supply's voltage equal the sum of every drop on the way to the load and back, including the ground return.", why: "Ground offsets, sag and mystery currents are all KVL and KCL applied honestly.", relatedLesson: "circuit-laws-on-the-bench" },
  { id: "time-constant", term: "time constant", aliases: ["RC time constant", "tau"], short: "The time an RC (or L/R) circuit takes to get 63 percent of the way to its final value; about five of them means settled.", detail: "τ = R × C in seconds for ohms and farads. Charging follows 1 − e^(−t/τ): 63 % at τ, 95 % at 3τ, 99.3 % at 5τ. The time to reach a fraction f is −τ ln(1 − f).", why: "Debounce timing, reset delays, filter settling and PWM smoothing are all 'how many time constants'.", relatedLesson: "capacitors-inductors-rc-and-filters" },
  { id: "cutoff-frequency", term: "cutoff frequency", aliases: ["−3 dB point", "-3 dB point", "corner frequency", "f_c"], short: "The frequency at which a filter's output has fallen to 0.707 of its input, the boundary between what it passes and what it attenuates.", detail: "For a first-order RC filter f_c = 1 / (2πRC). Beyond it the response falls 20 dB per decade. The same RC that gives a 1 ms time constant gives a 159 Hz cutoff.", why: "Anti-alias filters, PWM smoothing and rail filtering are specified by this one number.", relatedLesson: "capacitors-inductors-rc-and-filters" },
  { id: "hysteresis", term: "hysteresis", aliases: ["Schmitt trigger", "Schmitt input"], short: "Two different thresholds, one for switching up and a lower one for switching down, so a slow or noisy signal cannot flip the output back and forth.", detail: "A Schmitt-trigger input has hysteresis built in; most MCU GPIO inputs have a little. Without it an RC-slowed edge dwells in the forbidden band and the input chatters.", why: "The right fix for a bouncing button is hysteresis or firmware debounce, not a bigger capacitor.", relatedLesson: "capacitors-inductors-rc-and-filters" },
  { id: "esr", term: "ESR", aliases: ["equivalent series resistance"], short: "The resistance a real capacitor has in series with its capacitance, which sets its ripple heating and whether a regulator stays stable with it.", detail: "Electrolytics have tens of milliohms to ohms; ceramics have milliohms. A regulator designed for an ESR range may oscillate with a capacitor outside it; the datasheet's stability table is the law.", why: "'I upgraded the capacitor to a ceramic and the regulator started ringing' is a classic bench story.", relatedLesson: "capacitors-inductors-rc-and-filters" },
  { id: "mosfet", term: "MOSFET", aliases: ["MOSFETs", "N-channel MOSFET", "P-channel MOSFET", "logic-level MOSFET"], short: "A transistor that switches current between drain and source when enough voltage is applied to its gate; the standard power switch in firmware-controlled circuits.", detail: "As a switch it is read from V_DS(max), current, R_DS(on) at the available gate voltage and gate charge. V_GS(th) only says where conduction begins; a logic-level part specifies R_DS(on) at 2.5 or 3.3 V.", why: "Driving a heater or motor from a GPIO is the first circuit most firmware engineers design, and the threshold-voltage trap is the usual mistake.", relatedLesson: "diodes-and-transistors-as-switches" },
  { id: "flyback-diode", term: "flyback diode", aliases: ["freewheeling diode", "flyback"], short: "A diode across a coil or motor that gives its current somewhere to go when the switch opens, so the voltage cannot spike and destroy the transistor.", detail: "An inductor's current cannot stop instantly (V = L dI/dt). The diode sits across the load with its cathode to the positive supply, rated above the load current; fast or Schottky types for PWM.", why: "A relay driver without one works for a while and then the transistor dies; reviewers look for it first.", relatedLesson: "diodes-and-transistors-as-switches" },
  { id: "forced-beta", term: "forced beta", aliases: ["BJT saturation", "saturated switch"], short: "The fully-on state of a bipolar transistor switch, where more base current changes nothing and the collector sits a few tenths of a volt above the emitter.", detail: "Design for it with a forced beta of about 10: base current equal to one tenth of the collector current, R_B = (V_pin − 0.7 V) / I_B, so the switch stays on across temperature and part spread.", why: "A BJT run in its linear region as a 'switch' dissipates heat and switches slowly; interviewers ask how you guarantee saturation.", relatedLesson: "diodes-and-transistors-as-switches" },
  { id: "noise-margin", term: "noise margin", short: "How far an output's guaranteed level sits beyond the receiving input's threshold; the room that supply noise and ground offsets can eat before the bit is misread.", detail: "High-side margin = V_OH(driver) − V_IH(receiver); low-side = V_IL(receiver) − V_OL(driver). Both must be positive by a few hundred millivolts. CMOS thresholds are about 0.3 and 0.7 of the receiver's supply.", why: "Two datasheet lines and a subtraction decide whether a 3.3 V part can talk to a 5 V part; the question comes up in every schematic review and most interviews.", relatedLesson: "logic-levels-thresholds-and-open-drain" },
  { id: "injection-current", term: "injection current", short: "Current forced into a chip through a pin's clamp diode when the pin is driven beyond its supply or below ground.", detail: "Datasheets limit it to a few milliamps per pin. It flows into the chip's supply rail and can lift a lightly loaded rail; a series resistor keeps it within the limit.", why: "Explains why forcing 5 V into a 3.3 V input raised the whole rail and moved every threshold on the chip.", relatedLesson: "logic-levels-thresholds-and-open-drain" },
  { id: "ground-plane", term: "ground plane", aliases: ["return path", "return current", "common-impedance coupling"], short: "A whole copper layer used as ground, so return currents have a low-impedance path right under their signal and shared-trace voltage drops disappear.", detail: "Return current for a fast signal flows in the plane directly beneath the trace, the path of least inductance; a slot under the trace forces a detour that radiates and picks up noise. Analogue and digital regions of one plane meet once, at the converter.", why: "Shared ground returns shift sensor references by I × R; the plane is the fix, and a split plane is the classic self-inflicted wound.", relatedLesson: "grounding-protection-and-the-first-thing-that-breaks" },
  { id: "tvs-diode", term: "TVS diode", aliases: ["TVS", "transient voltage suppressor"], short: "A protection diode that stays out of the way at normal voltages and clamps a static discharge or surge to a safe level in nanoseconds.", detail: "Chosen by reverse stand-off voltage (at or above the normal signal), clamping voltage at the rated pulse current (below the protected pin's absolute maximum) and peak pulse power. Placed at the connector; low-capacitance types for fast signals.", why: "'What protects this input?' expects the part and its two voltages, not just the name.", relatedLesson: "grounding-protection-and-the-first-thing-that-breaks" },
  { id: "burden-voltage", term: "burden voltage", short: "The voltage a multimeter's current range drops across its own shunt, which it steals from the circuit it is measuring.", detail: "Up to a few hundred millivolts on milliamp ranges and with thin leads: 0.35 A through 1.2 Ω is 0.42 V. It can sag a 3.3 V rail enough to reset the board under test.", why: "The measurement is honest and the circuit is changed; knowing this separates a real sag from a meter-induced one.", relatedLesson: "the-dmm-and-the-bench-supply" },
  // --- Embedded C foundations and STM32 ---
  { id: "linkage", term: "linkage", aliases: ["internal linkage", "external linkage", "file-scope static"], short: "Whether a name declared in one source file can be seen from other files; static at file level makes it private to the file.", detail: "A file-level variable or function has external linkage by default (any file can refer to it); static gives internal linkage. Two files defining the same external name collide at link time.", why: "Make everything static unless the header exposes it; it is the first thing a reviewer looks for in a driver file.", relatedLesson: "c-foundations-for-firmware" },
  { id: "array-decay", term: "array decay", aliases: ["decays to a pointer", "pointer arithmetic"], short: "When an array is passed to a function or used in an expression it becomes a pointer to its first element and forgets its length.", detail: "Inside the function sizeof gives the pointer's size, not the array's. Pointer arithmetic moves in elements (p + 1 on a uint32_t pointer is four bytes). Carry the length as a separate parameter.", why: "Most buffer overruns start with a function that assumed it knew the array's size.", relatedLesson: "c-foundations-for-firmware" },
  { id: "struct-padding", term: "struct padding", aliases: ["padding", "alignment padding"], short: "Bytes the compiler inserts between and after struct members so each sits at an address its type requires; the struct is bigger than the sum of its members.", detail: "On 32-bit Arm, 32-bit members sit at multiples of 4 and the struct size is rounded to its largest alignment: { uint8_t; uint32_t; uint16_t } is 12 bytes for 7 of data. Order largest first; never overlay a struct on wire bytes without serialising.", why: "sizeof surprises, wire-protocol mismatches and the register-overlay pattern all come down to padding.", relatedLesson: "c-foundations-for-firmware" },
  { id: "memory-sections", term: "memory sections", aliases: [".rodata", ".text", "rodata", "linker sections"], short: "The regions a linker sorts a program into: code and constants in flash, initialised and zeroed variables in RAM, plus the stack and heap.", detail: ".text is code, .rodata is const data (flash); .data is initialised globals copied from flash to RAM at start-up; .bss is zeroed globals; the stack grows down from the top of RAM and the heap sits between. The map file lists every symbol's section and size.", why: "Knowing which section a variable lands in explains RAM use, start-up time and why a stray write corrupts a neighbour.", relatedLesson: "stack-heap-and-where-your-variables-live" },
  { id: "stack-overflow", term: "stack overflow", aliases: ["stack frame", "stack frames"], short: "The stack pointer passing the end of the memory reserved for it and overwriting whatever lies below, usually silently.", detail: "Each call pushes a frame (return address, saved registers, locals); interrupts push their own frames on top. Size the stack from a measured high-water mark plus margin, place it at the bottom of RAM so an overflow faults, keep handler frames small.", why: "The variable that changes though nobody writes it is almost always this.", relatedLesson: "stack-heap-and-where-your-variables-live" },
  { id: "state-machine", term: "state machine", aliases: ["state machines", "transition table", "finite state machine"], short: "A design where the system is always in exactly one named state and a table says what each event does in each state.", detail: "In C: an enum of states, a context struct, one function that performs every state change with its entry and exit actions, and a switch handling every event. Time is an event (a tick), so no delays; hardware behind a seam so a host test can drive it.", why: "Flags that mean three things and delays in control flow are the two smells; explicit machines are what reviewers and interviewers want to see.", relatedLesson: "state-machines-that-survive-review" },
  { id: "ring-buffer", term: "ring buffer", aliases: ["circular buffer", "ring buffers", "head and tail"], short: "A fixed array treated as a circle, filled by a producer at the head and emptied by a consumer at the tail, so bytes queue between an interrupt and the main loop.", detail: "Empty when head equals tail; full when head + 1 equals tail (one slot kept empty). Lock-free for one producer and one consumer when each index has one writer, data is written before the index is published, and index stores are atomic.", why: "Every serial driver has one, and writing it is the standard embedded coding-interview task.", relatedLesson: "a-ring-buffer-for-the-uart-driver" },
  { id: "overrun", term: "overrun", aliases: ["overruns", "ORE flag", "buffer overrun"], short: "Data arriving when there is nowhere to put it: a full buffer, or a UART data register not read before the next byte lands.", detail: "A receive design decides what happens (refuse and count, or overwrite the oldest) and exposes the count. The STM32 USART sets ORE when its one-byte register is overrun; a ring buffer that is full returns false to the caller.", why: "A non-zero overrun counter turns 'the link is unreliable' into a sizing problem with a number.", relatedLesson: "a-ring-buffer-for-the-uart-driver" },
  { id: "hal", term: "HAL", aliases: ["hardware abstraction layer", "STM32 HAL", "LL drivers"], short: "The vendor's C library of functions that configure and drive peripherals by writing their registers for you, portable across the chip family.", detail: "HAL_GPIO_WritePin is one store to BSRR; HAL_RCC_ClockConfig programs the PLL and waits for the ready flags. The low-layer (LL) drivers are thinner wrappers; bare CMSIS register access is what both compile to. Read the HAL once so you know what it does.", why: "Interviewers ask what a HAL call actually writes; the answer separates users of the tool from engineers of the chip.", relatedLesson: "your-first-stm32-project" },
  { id: "cubemx", term: "CubeMX", aliases: ["STM32CubeMX", "STM32CubeIDE", "CubeIDE", "USER CODE markers"], short: "ST's configuration tool and IDE that generate the pin, clock and peripheral set-up code for an STM32 project.", detail: "Generates main.c, MSP and interrupt files, startup assembly and the linker script from a .ioc file. Only code between USER CODE BEGIN/END markers survives regeneration; keep your modules in separate files.", why: "The first STM32 project everyone creates; knowing what it generated is the difference between a tutorial and a design.", relatedLesson: "your-first-stm32-project" },
  { id: "pll", term: "PLL", aliases: ["phase-locked loop", "VCO", "PLL dividers"], short: "The circuit that multiplies a low oscillator frequency up to the system clock, through a divide-by-M, multiply-by-N and divide-by-P chain with range limits at each stage.", detail: "On the F4: source / M must be 1 to 2 MHz; × N must land the VCO in 192 to 432 MHz; / P (2, 4, 6, 8) is the PLL output; / Q gives 48 MHz for USB. 16 / 16 × 336 / 4 = 84 MHz. The firmware waits for PLLRDY before switching to it.", why: "Clock-tree arithmetic is a standard interview question and the root of every 'timer runs at the wrong rate' bug.", relatedLesson: "gpio-and-the-clock-tree" },
  { id: "apb-timer-clock", term: "timer clock rule", aliases: ["APB1", "APB2", "bus prescaler", "timer doubling"], short: "On STM32F4 parts, a timer on a bus whose prescaler is not 1 is clocked at twice the bus frequency.", detail: "APB1 at 42 MHz (prescaler 2) clocks TIM2 to TIM7 at 84 MHz; USART and I2C on the same bus use 42 MHz. RCC_DCKCFGR TIMPRE changes the rule; the reference manual's clock-tree figure has the footnote.", why: "A PWM at exactly twice the designed frequency is this rule missed.", relatedLesson: "gpio-and-the-clock-tree" },
  { id: "mco", term: "MCO", aliases: ["microcontroller clock output", "clock output pin"], short: "A pin that can output an internal clock (HSI, HSE, PLL or SYSCLK, divided) so you can measure it with a scope.", detail: "On the F4, MCO1 on PA8 and MCO2 on PC9 with dividers 1 to 5. The measured frequency is the truth; SystemCoreClock is what the firmware intended.", why: "One scope measurement turns the clock configuration from belief into evidence.", relatedLesson: "gpio-and-the-clock-tree" },
  { id: "mcu-mpu-soc", term: "MPU", aliases: ["microprocessor", "SoC", "system-on-chip", "application processor"], short: "A processor with no useful program memory on chip: it boots from external storage into external RAM and runs an operating system, unlike a microcontroller.", detail: "MPUs (i.MX, AM335x, Raspberry Pi's chips) take seconds to boot Linux, draw watts and offer no hard real-time guarantee alone. An SoC integrates several subsystems, often an MPU core with an MCU core beside it for the real-time work.", why: "Choosing the kind of computer before the part is the first design decision, and interviewers test it.", relatedLesson: "choosing-and-reading-an-mcu" },
  { id: "cortex-m", term: "Cortex-M", aliases: ["Cortex-M4F", "Cortex-M0+", "Cortex-M7", "Cortex-R", "Cortex-A", "Arm core"], short: "The family of Arm processor cores built into most 32-bit microcontrollers; the letter is the role and the number the capability.", detail: "M0+ minimal, M3 general, M4F adds DSP instructions and a single-precision FPU, M7 adds caches and performance, M33 adds TrustZone. Cortex-R is for hard real-time with safety features; Cortex-A has an MMU and runs Linux.", why: "'Cortex-M4F at 84 MHz' in a job advert tells you float is fast and double is not, and what NVIC you have.", relatedLesson: "choosing-and-reading-an-mcu" },
  { id: "part-number", term: "part number", aliases: ["ordering code", "STM32 part number"], short: "The code on the chip that encodes its family, line, pin count, memory size, package and temperature grade.", detail: "STM32F446RET6: F4 series, 446 line (Cortex-M4F), R = 64 pins, E = 512 kB flash, T = LQFP, 6 = −40 to 85 °C. The datasheet's ordering-information section decodes each vendor's scheme.", why: "Reading a schematic's part number tells you in seconds whether the chip has the peripheral, the pins and the temperature range you need.", relatedLesson: "choosing-and-reading-an-mcu" },
  { id: "stop-mode", term: "Stop mode", aliases: ["Sleep mode", "Standby mode", "low-power mode", "low-power modes", "deep sleep"], short: "The three depths of microcontroller sleep: Sleep halts the core, Stop halts all clocks but keeps RAM, Standby powers the core domain off and keeps only the RTC and backup registers.", detail: "Sleep wakes in cycles at milliamps; Stop wakes on EXTI or RTC in tens of microseconds plus a clock restart at tens to hundreds of microamps; Standby wakes through reset at a few microamps and loses RAM. Firmware restores clocks and clears wake-up flags after Stop.", why: "Choosing the mode is a trade between the floor current and what it costs to wake; the wrong choice is a dead battery or a missed deadline.", relatedLesson: "low-power-modes-and-wake-up-sources" },
  { id: "wake-up-source", term: "wake-up source", aliases: ["EXTI", "external interrupt", "RTC wake-up timer", "WKUP pin"], short: "The event allowed to bring a sleeping microcontroller back: an edge on a pin routed through the external-interrupt controller, an RTC alarm or timer, or a low-power peripheral.", detail: "EXTI maps one line per pin number across ports (PA0, PB0 and PC0 share EXTI0). From Standby only the dedicated WKUP pins and the RTC work. The RTC runs from LSE (accurate crystal) or LSI (±50 % RC).", why: "A node that never wakes, or wakes and hangs, is a wake-up source or wake-up path problem.", relatedLesson: "low-power-modes-and-wake-up-sources" },
  // --- Avionics data buses (MIL-STD-1553B) ---
  { id: "mil-std-1553b", term: "MIL-STD-1553B", aliases: ["1553B", "1553 bus", "MIL-STD-1553"], short: "A military and aerospace data bus where one controller asks and terminals answer, one megabit per second, in fixed 20-bit words.", detail: "Command/response time-division multiplexing over a dual-redundant shielded twisted pair with Manchester II coding; up to 31 remote terminals plus broadcast; words are 3 bit times of sync, 16 data bits and an odd-parity bit.", why: "On the skills line of most avionics job descriptions; decoding a captured word by hand is what turns 'familiar with' into 'has used'.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "bus-controller", term: "bus controller", aliases: ["BC"], short: "The one device on a 1553 bus that starts every exchange by sending command words.", detail: "Only the bus controller sends command words; it schedules which terminal is addressed when (major and minor frames), judges response timing, and retries, usually on the other bus, after a no-response.", why: "Most 'the terminal is faulty' investigations end in the controller's schedule.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "remote-terminal", term: "remote terminal", aliases: ["remote terminals", "RT"], short: "A device on a 1553 bus that speaks only when the bus controller addresses it.", detail: "Addressed by a 5-bit address (0 to 30); answers a command within 4 to 12 µs with a status word, then data words if asked to transmit; rejects words with bad parity or Manchester errors without responding.", why: "Knowing what a terminal does with a command it cannot serve explains most no-response faults.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "bus-monitor", term: "bus monitor", aliases: ["bus analyser", "bus analyzer"], short: "A device that listens to everything on the bus and records it without ever transmitting.", detail: "Used for integration test and flight-data recording; shows each word with its sync type, decoded fields, parity result and the response time, and marks commands that received no response.", why: "The primary evidence in an avionics integration lab.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "manchester", term: "Manchester II", aliases: ["Manchester coding", "Manchester", "bi-phase"], short: "A way of sending bits where every bit is a transition in the middle of its time slot: 1 is high then low, 0 is low then high.", detail: "Self-clocking (the receiver recovers the bit clock from the transitions) and free of DC content, so the signal passes through coupling transformers. 1553 uses it at 1 Mbit/s; the sync pattern deliberately breaks the rule so it can never appear inside data.", why: "Explains why 1553 has no baud-tolerance problem and why terminals can be transformer isolated." },
  { id: "command-word", term: "command word", aliases: ["command words"], short: "The 1553 word the bus controller sends to tell a terminal what to do.", detail: "Sixteen data bits: remote terminal address (5), transmit/receive (1), subaddress or mode (5), word count or mode code (5). Address 31 is broadcast; subaddress 0 or 31 marks a mode command; word count 0 means 32.", why: "Reading these four fields by hand is the single most useful 1553 skill.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "status-word", term: "status word", aliases: ["status words"], short: "The first word a terminal sends back: its own address and a set of flags saying how the command went.", detail: "Flags include message error, instrumentation, service request, broadcast command received, busy, subsystem flag, dynamic bus control acceptance and terminal flag. All zero is a clean answer; the address lets the controller confirm who replied.", why: "A flagged status is an answer; silence is a different fault. Telling them apart saves a day.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "subaddress", term: "subaddress", aliases: ["subaddresses"], short: "A numbered mailbox inside a 1553 terminal that a command reads from or writes to.", detail: "Five bits, 1 to 30 for data; 0 and 31 mark the command as a mode command instead. What each subaddress holds, and how many words, is defined in the terminal's interface control document.", why: "A command for a subaddress or word count the terminal does not implement is the classic repeatable no-response.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "mode-code", term: "mode code", aliases: ["mode codes", "mode command"], short: "A 1553 command that manages the terminal itself rather than moving data: transmit your status, reset, synchronise.", detail: "Signalled by subaddress 0 or 31; the five-bit field that would hold the word count holds the code instead (for example 2 = transmit status word, 8 = reset remote terminal). Some mode codes carry one data word.", why: "The field that changes meaning depending on another field is the trap in every 1553 decode question.", relatedLesson: "mil-std-1553b-the-word-and-the-message" },
  { id: "priority-ceiling", term: "priority ceiling", aliases: ["ceiling protocol", "immediate ceiling"], short: "A locking rule that raises any task taking a lock straight to the highest priority of every task that ever uses that lock.", detail: "The immediate priority ceiling protocol (used by OSEK/AUTOSAR OS) needs design-time knowledge of which tasks use which locks; in return it bounds blocking to one critical section and prevents deadlock between nested locks.", why: "The design-time alternative to priority inheritance; knowing which your kernel uses is a Tier-2 RTOS answer.", relatedLesson: "priority-inversion" },
  { id: "load-transient", term: "load transient", aliases: ["load step", "transient response"], short: "What a regulator's output does when its load current jumps suddenly: a dip, then an overshoot, before it settles.", detail: "Set by the regulator's control-loop speed and by the output capacitance and its ESR; every regulator datasheet gives the capacitance and ESR range it stays stable with. Outside that range the output rings or oscillates.", why: "The second power problem that appears after the first (sag) is fixed with a big capacitor.", relatedLesson: "reading-a-power-tree" },
];

const byId = new Map(glossary.map((g) => [g.id, g]));
export function getTerm(id: string): GlossaryTerm | undefined {
  return byId.get(id);
}
